import React from "react";
import { BrowserRouter as Router, Route, Routes } from "react-router-dom";
import { Container, ThemeProvider, CssBaseline } from "@mui/material";

import ErrorBoundary from "./components/ErrorBoundary.jsx";
import Header from "./components/header.jsx";
import Landing from "../src/pages/landingPage.jsx";
import { CustomThemeProvider, useThemeContext } from "../src/components/themeContext.jsx";
import ScrollToTopButton from "./components/ScrollToTopButton.jsx";
import Userpage from "./pages/userPage.jsx";
import AniListComponent from "./components/AniListComponent.jsx";

const AppContent = () => {
  const { currentTheme } = useThemeContext();
  return (
    <ThemeProvider theme={currentTheme}>
      <CssBaseline />
      <Router basename="/tsubaki">
        <Header />
        <ScrollToTopButton />
        <ErrorBoundary>
          <Container>
            <Routes>
              <Route path="/" element={<Landing />} />
              <Route path="/anilist" element={<AniListComponent />} />
              <Route path="/user/*" element={<Userpage />} />
            </Routes>
          </Container>
        </ErrorBoundary>
      </Router>
    </ThemeProvider>
  );
};

function App() {
  return (
    <CustomThemeProvider>
      <AppContent />
    </CustomThemeProvider>
  );
}

export default App;
