import React, { useState, useEffect } from "react";
import {
  Box,
  Card,
  CardContent,
  Typography,
  Grid,
  alpha,
  useTheme,
  CircularProgress,
  Divider,
  Tooltip,
  Button
} from "@mui/material";
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip as RechartsTooltip, 
  ResponsiveContainer,
  Cell
} from "recharts";
import CalendarTodayIcon from "@mui/icons-material/CalendarToday";
import TrendingUpIcon from "@mui/icons-material/TrendingUp";
import { WEEKLY_ACTIVITY_QUERY, fetchFromAniList } from "../../../../queries/queries";

/**
 * Weekly Report component that shows anime/manga consumption for the past week
 * Inspired by Last.fm's weekly listening report
 */
const WeeklyReport = ({ userId, mediaType, paperStyles, formatTime, generateColors }) => {
  const theme = useTheme();
  const [weeklyData, setWeeklyData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [timeframe, setTimeframe] = useState("week"); // Only weekly timeframe will be supported
  
  // Get date range for selected timeframe
  const getDateRange = () => {
    const today = new Date();
    const startDate = new Date(today);
    startDate.setDate(today.getDate() - 7);
    
    const endDate = today;
    
    // Format dates for display
    const options = { month: 'short', day: 'numeric' };
    return {
      displayRange: `${startDate.toLocaleDateString('en-US', options)} - ${endDate.toLocaleDateString('en-US', options)}`,
      startDate: formatDateForApi(startDate),
      endDate: formatDateForApi(endDate)
    };
  };
  
  // Format a date for the API (YYYYMMDD format for FuzzyDateInt)
  const formatDateForApi = (date) => {
    // AniList's FuzzyDateInt format: YYYYMMDD as an integer value
    return parseInt(
      date.getFullYear() * 10000 + 
      (date.getMonth() + 1) * 100 + 
      date.getDate()
    );
  };
  
  // Fetch weekly activity data
  useEffect(() => {
    const fetchWeeklyData = async () => {
      try {
        setLoading(true);
        setError(null);
        
        const dateRange = getDateRange();
        
        // Fetch actual data from the API
        try {
          console.log("Fetching weekly activity data with params:", { 
            userId: parseInt(userId), 
            startDate: dateRange.startDate,
            endDate: dateRange.endDate
          });
          
          const response = await fetchFromAniList(WEEKLY_ACTIVITY_QUERY, { 
            userId: parseInt(userId), 
            startDate: dateRange.startDate,
            endDate: dateRange.endDate
          });
          
          console.log("Weekly activity API response:", response);
          
          // Process real data from the API response
          if (response && response.Page && response.Page.activities) {
            const activities = response.Page.activities;
            
            // If no activities found, show "no activity" state
            if (activities.length === 0) {
              setWeeklyData({
                hasActivity: false,
                timeframe,
                displayRange: dateRange.displayRange
              });
              setLoading(false);
              return;
            }
            
            // Get genres from user statistics if available
            const userStats = response.User?.statistics;
            const topGenres = userStats && userStats[mediaType]?.genres
              ? [...userStats[mediaType].genres]
                  .sort((a, b) => b.count - a.count)
                  .slice(0, 3)
                  .map(g => g.genre)
              : ["Action", "Drama", "Comedy"]; // Default fallback
            
            // Group activities by day of the week
            const daysOfWeek = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
            const dailyActivityMap = {};
            
            // Initialize each day with zero
            daysOfWeek.forEach(day => {
              dailyActivityMap[day] = { day, count: 0, time: 0 };
            });
            
            // Count activities per day
            activities.forEach(activity => {
              if (!activity.media) return;
              
              // Get day of week from activity createdAt timestamp
              const date = new Date(activity.createdAt * 1000);
              const dayOfWeek = daysOfWeek[date.getDay() === 0 ? 6 : date.getDay() - 1]; // Convert to Monday-Sunday
              
              dailyActivityMap[dayOfWeek].count += activity.progress || 1;
              
              // Calculate time watched if available (for anime)
              if (mediaType === "anime" && activity.media.duration) {
                dailyActivityMap[dayOfWeek].time += (activity.progress || 1) * activity.media.duration;
              }
            });
            
            // Convert map to array for chart
            const dailyActivity = Object.values(dailyActivityMap);
            
            // Find most active day
            const mostActive = [...dailyActivity].sort((a, b) => b.count - a.count)[0];
            const totalCount = dailyActivity.reduce((sum, day) => sum + day.count, 0);
            const totalTime = dailyActivity.reduce((sum, day) => sum + day.time, 0);
            const percentage = totalCount > 0 ? ((mostActive.count / totalCount) * 100).toFixed(1) : 0;
            
            // Group activities by media ID to count unique items
            const uniqueMedia = new Set();
            activities.forEach(activity => {
              if (activity.media && activity.media.id) {
                uniqueMedia.add(activity.media.id);
              }
            });
            
            setWeeklyData({
              hasActivity: true,
              timeframe,
              displayRange: dateRange.displayRange,
              totalItems: uniqueMedia.size,
              totalEpisodesOrChapters: totalCount,
              totalTimeSpent: totalTime,
              averagePerDay: (totalCount / 7).toFixed(1),
              topGenres,
              dailyActivity,
              mostActive: {
                day: mostActive.day,
                count: mostActive.count,
                percentage
              }
            });
          } else {
            // No activity found
            setWeeklyData({
              hasActivity: false,
              timeframe,
              displayRange: dateRange.displayRange
            });
          }
          setLoading(false);
        } catch (apiError) {
          console.error("API error:", apiError);
          setError("Failed to fetch your activity data. Please try again later.");
          setLoading(false);
        }
      } catch (err) {
        console.error("Error fetching weekly data:", err);
        setError(err.message);
        setLoading(false);
      }
    };
    
    fetchWeeklyData();
  }, [userId, mediaType, timeframe]);
  
  if (loading) {
    return (
      <Card sx={{ ...paperStyles, mb: 3 }}>
        <CardContent sx={{ textAlign: 'center', py: 5 }}>
          <CircularProgress size={40} />
          <Typography variant="body2" sx={{ mt: 2 }}>
            Gathering your {timeframe}ly activity...
          </Typography>
        </CardContent>
      </Card>
    );
  }
  
  if (error) {
    return (
      <Card sx={{ ...paperStyles, mb: 3 }}>
        <CardContent>
          <Typography variant="h6" color="error">
            Couldn't load {timeframe}ly report
          </Typography>
          <Typography variant="body2">{error}</Typography>
        </CardContent>
      </Card>
    );
  }
  
  if (!weeklyData) {
    return (
      <Card sx={{ ...paperStyles, mb: 3 }}>
        <CardContent>
          <Typography variant="h6">No {timeframe}ly data available</Typography>
          <Typography variant="body2">
            We don't have enough data about your recent activity.
          </Typography>
        </CardContent>
      </Card>
    );
  }
  
  // Handle no activity case
  if (!weeklyData.hasActivity) {
    return (
      <Card sx={{ ...paperStyles, mb: 3 }}>
        <CardContent>
          <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
            <CalendarTodayIcon sx={{ color: theme.palette.primary.main, mr: 1 }} />
            <Typography variant="h6" sx={{ fontWeight: 600 }}>
              Your weekly {mediaType} report
            </Typography>
          </Box>
          
          <Typography variant="body2" color="text.secondary" sx={{ my: 2 }}>
            {weeklyData.displayRange}
          </Typography>
          
          <Box sx={{ 
            py: 4, 
            display: 'flex', 
            flexDirection: 'column', 
            alignItems: 'center',
            justifyContent: 'center' 
          }}>
            <Box sx={{ 
              width: 60, 
              height: 60, 
              borderRadius: '50%', 
              backgroundColor: alpha(theme.palette.text.secondary, 0.1),
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              mb: 2
            }}>
              <CalendarTodayIcon color="action" sx={{ fontSize: 30 }} />
            </Box>
            <Typography variant="h6" color="text.secondary">
              No activity during this week
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mt: 1, maxWidth: 400, textAlign: 'center' }}>
              You didn't {mediaType === "anime" ? "watch any anime" : "read any manga"} this week.
            </Typography>
          </Box>
        </CardContent>
      </Card>
    );
  }
  
  // Generate colors for charts
  const chartColors = generateColors(7);
  
  return (
    <Card 
      sx={{ 
        ...paperStyles, 
        mb: 3,
        overflow: 'hidden'
      }}
    >
      <CardContent>
        <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
          <CalendarTodayIcon sx={{ color: theme.palette.primary.main, mr: 1 }} />
          <Typography variant="h6" sx={{ fontWeight: 600 }}>
            Your weekly {mediaType} report
          </Typography>
        </Box>
        
        <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
          {weeklyData.displayRange}
        </Typography>
        
        {/* Weekly summary */}
        <Grid container spacing={3} sx={{ mb: 3 }}>
          <Grid item xs={12} sm={6} md={3}>
            <Box>
              <Typography variant="caption" color="text.secondary">
                {mediaType === "anime" ? "ANIME WATCHED" : "MANGA READ"}
              </Typography>
              <Typography variant="h4" sx={{ fontWeight: 'bold', my: 0.5 }}>
                {weeklyData.totalItems}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                {weeklyData.averagePerDay} per day on average
              </Typography>
            </Box>
          </Grid>
          
          <Grid item xs={12} sm={6} md={3}>
            <Box>
              <Typography variant="caption" color="text.secondary">
                {mediaType === "anime" ? "EPISODES WATCHED" : "CHAPTERS READ"}
              </Typography>
              <Typography variant="h4" sx={{ fontWeight: 'bold', my: 0.5 }}>
                {weeklyData.totalEpisodesOrChapters}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                across {weeklyData.totalItems} different {mediaType}
              </Typography>
            </Box>
          </Grid>
          
          <Grid item xs={12} sm={6} md={3}>
            <Box>
              <Typography variant="caption" color="text.secondary">
                {mediaType === "anime" ? "TIME WATCHED" : "VOLUME EQUIVALENT"}
              </Typography>
              <Typography variant="h4" sx={{ fontWeight: 'bold', my: 0.5 }}>
                {mediaType === "anime" 
                  ? formatTime(weeklyData.totalTimeSpent) 
                  : Math.round(weeklyData.totalEpisodesOrChapters / 5)}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                {mediaType === "anime" 
                  ? `${Math.round(weeklyData.totalTimeSpent / 60)} hours total` 
                  : "estimated volumes"}
              </Typography>
            </Box>
          </Grid>
          
          <Grid item xs={12} sm={6} md={3}>
            <Box>
              <Typography variant="caption" color="text.secondary">
                MOST ACTIVE DAY
              </Typography>
              <Typography variant="h4" sx={{ fontWeight: 'bold', my: 0.5 }}>
                {weeklyData.mostActive.day}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                {weeklyData.mostActive.count} {mediaType === "anime" ? "episodes" : "chapters"} ({weeklyData.mostActive.percentage}%)
              </Typography>
            </Box>
          </Grid>
        </Grid>
        
        <Divider sx={{ my: 2 }} />
        
        {/* Daily Activity Chart */}
        <Typography variant="subtitle1" sx={{ fontWeight: 600, mb: 2 }}>
          Daily Activity
        </Typography>
        
        <Box sx={{ height: 250, mb: 2 }}>
          <ResponsiveContainer width="100%" height="100%">
            <BarChart
              data={weeklyData.dailyActivity}
              margin={{ top: 10, right: 10, left: 0, bottom: 0 }}
            >
              <CartesianGrid strokeDasharray="3 3" vertical={false} />
              <XAxis 
                dataKey="day" 
                axisLine={false}
                tickLine={false}
              />
              <YAxis 
                axisLine={false}
                tickLine={false}
                tickFormatter={(value) => value}
              />
              <RechartsTooltip
                formatter={(value, name, props) => [
                  mediaType === "anime" 
                    ? `${value} episodes (${formatTime(props.payload.time)})` 
                    : `${value} chapters`,
                  props.payload.day
                ]}
              />
              <Bar 
                dataKey="count" 
                radius={[4, 4, 0, 0]}
              >
                {weeklyData.dailyActivity.map((entry, index) => (
                  <Cell 
                    key={`cell-${index}`} 
                    fill={chartColors[index % chartColors.length]} 
                  />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </Box>
        
        {/* Top Genres */}
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mb: 2 }}>
          <Typography variant="body2" sx={{ fontWeight: 600, mr: 1 }}>
            Top Genres:
          </Typography>
          {weeklyData.topGenres.map((genre, index) => (
            <Tooltip key={genre} title={`${genre} was your #${index + 1} genre`}>
              <Box 
                sx={{ 
                  px: 1.5, 
                  py: 0.5, 
                  borderRadius: 10, 
                  backgroundColor: alpha(chartColors[index], 0.15),
                  color: chartColors[index],
                  fontSize: '0.75rem',
                  fontWeight: 'bold'
                }}
              >
                {genre}
              </Box>
            </Tooltip>
          ))}
        </Box>
      </CardContent>
    </Card>
  );
};

export default WeeklyReport;
