import React, { useState, useEffect, useMemo } from "react";
import {
  Box,
  Paper,
  Typography,
  CircularProgress,
  Alert,
  useTheme,
  useMediaQuery,
  styled,
  Fade,
  Backdrop,
  IconButton
} from "@mui/material";
import { useLocation, useNavigate, Routes, Route } from "react-router-dom";
import MenuIcon from "@mui/icons-material/Menu";
import CloseIcon from "@mui/icons-material/Close";

import SectionNav from "../components/userpage/sectionNav.jsx";
import Overview from "../pages/userpage/overview.jsx";
import UserMangaList from "./userpage/user-lists/userMangaList.jsx";
import UserSidebar from "../../src/pages/userpage/userSidebar.jsx";
import Statistics from "./userpage/statistics/statistics.jsx";
import { USER_QUERY, ACTIVITY_QUERY, FAVORITES_QUERY } from "../queries/queries.js";

// Improved Mobile Menu Button
const MobileMenuButton = styled(IconButton)(({ theme }) => ({
  position: "fixed",
  top: 12,
  left: 12,
  zIndex: 1300,
  backgroundColor: theme.palette.primary.main,
  color: theme.palette.common.white,
  padding: 8,
  boxShadow: theme.shadows[2],
  "&:hover": {
    backgroundColor: theme.palette.primary.dark,
  },
}));

// Full-width content container that scales with sidebar
const ContentContainer = styled(Box, {
  shouldForwardProp: (prop) => !["isMobile", "sidebarOpen", "sidebarWidth"].includes(prop),
})(({ theme, isMobile, sidebarOpen, sidebarWidth }) => ({
  flexGrow: 1,
  minHeight: "100vh",
  transition: "margin 0.3s ease, padding 0.3s ease",
  //padding: isMobile ? theme.spacing(2, 1.5) : theme.spacing(3, 2),
  //paddingTop: isMobile ? theme.spacing(7) : theme.spacing(3),
  width: "auto",
  maxWidth: "100%",
}));

// Streamlined Dashboard Card
const DashboardCard = styled(Paper)(({ theme }) => ({
  marginBottom: theme.spacing(3),
  width: "100%",
  height: "100%",
  overflow: "hidden",
}));

// Improved loading state
const LoadingState = ({ theme }) => (
  <Backdrop open={true} sx={{ zIndex: theme.zIndex.drawer + 1 }}>
    <Box sx={{ textAlign: "center" }}>
      <CircularProgress color="primary" size={50} thickness={4} />
      <Typography variant="body1" color="white" sx={{ mt: 2 }}>
        Loading dashboard...
      </Typography>
    </Box>
  </Backdrop>
);

// Simplified error state
const ErrorState = ({ error }) => (
  <Box sx={{ p: 3, maxWidth: 600, mx: "auto", mt: 4 }}>
    <Alert severity="error" variant="filled">
      <Typography variant="subtitle1" fontWeight="medium">
        Error loading dashboard
      </Typography>
      <Typography variant="body2" sx={{ mt: 1 }}>
        {error}
      </Typography>
    </Alert>
  </Box>
);

const UserPage = () => {
  const theme = useTheme();
  const location = useLocation();
  const navigate = useNavigate();
  const [userData, setUserData] = useState(null);
  const [activities, setActivities] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [myListsExpanded, setMyListsExpanded] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  
  // Sidebar width matches the width in UserSidebar component
  const sidebarWidth = 220;

  // Responsive handling
  const isMobile = useMediaQuery(theme.breakpoints.down("md"));

  // Close sidebar on mobile by default
  useEffect(() => {
    setSidebarOpen(!isMobile);
  }, [isMobile]);

  // Redirect from "/user" to "/user/overview"
  useEffect(() => {
    if (location.pathname === "/user") {
      navigate("/user/overview", { replace: true });
    }
  }, [location.pathname, navigate]);

  // Check if a route is active
  const isRouteActive = (path) => {
    return location.pathname.startsWith(path);
  };

  useEffect(() => {
    const fetchUserData = async () => {
      try {
        const username = "ajisai";

        // Fetch user data
        const response = await fetch("https://graphql.anilist.co", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Accept: "application/json",
          },
          body: JSON.stringify({
            query: USER_QUERY(username),
          }),
        });

        const result = await response.json();
        if (result.errors) throw new Error(result.errors[0].message);
        setUserData(result.data.User);

        // Fetch user activities
        const activityResponse = await fetch("https://graphql.anilist.co", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Accept: "application/json",
          },
          body: JSON.stringify({
            query: ACTIVITY_QUERY,
            variables: { userId: result.data.User.id },
          }),
        });

        const activityResult = await activityResponse.json();
        if (activityResult.errors)
          throw new Error(activityResult.errors[0].message);
        setActivities(activityResult.data.Page.activities);

        // Fetch user favorites
        const favoritesResponse = await fetch("https://graphql.anilist.co", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Accept: "application/json",
          },
          body: JSON.stringify({
            query: FAVORITES_QUERY,
            variables: { userId: result.data.User.id },
          }),
        });

        const favoritesResult = await favoritesResponse.json();
        if (favoritesResult.errors)
          throw new Error(favoritesResult.errors[0].message);

        setUserData((prev) => ({
          ...prev,
          favourites: favoritesResult.data.User.favourites,
        }));

        setLoading(false);
      } catch (error) {
        console.error("Error fetching user data:", error);
        setError(error.message);
        setLoading(false);
      }
    };

    fetchUserData();
  }, []);

  const toggleSidebar = () => {
    setSidebarOpen(!sidebarOpen);
  };

  const toggleMyLists = () => {
    setMyListsExpanded(!myListsExpanded);
  };

  if (loading) return <LoadingState theme={theme} />;
  if (error) return <ErrorState error={error} />;

  return (
    <Box
      aria-label="Dashboard page"
      sx={{
        display: "flex",
        minHeight: "100vh",
        position: "relative",
        backgroundColor: theme.palette.background.default,
      }}
    >
      {/* Mobile Menu Button */}
      {isMobile && (
        <MobileMenuButton
          onClick={toggleSidebar}
          aria-label={sidebarOpen ? "Close sidebar" : "Open sidebar"}
          aria-expanded={sidebarOpen}
          size="small"
          sx={{ top: 64 }}
        >
          {sidebarOpen ? <CloseIcon /> : <MenuIcon />}
        </MobileMenuButton>
      )}

      {/* Sidebar */}
      <UserSidebar
        userData={userData}
        myListsExpanded={myListsExpanded}
        toggleMyLists={toggleMyLists}
        isRouteActive={isRouteActive}
        sidebarOpen={sidebarOpen}
      />

      {/* Main Content */}
      <ContentContainer 
        component="main" 
        isMobile={isMobile} 
        sidebarOpen={sidebarOpen}
        sidebarWidth={sidebarWidth}
        aria-label="Dashboard content"
      >
        <Fade in={true} timeout={200}>
          <Box sx={{ maxWidth: "100%" }}>
            <DashboardCard aria-label="Dashboard card">
              <Routes>
                <Route
                  path="overview"
                  element={<Overview userData={userData} activities={activities} userId={userData?.id} />}
                />
                <Route
                  path="lists/anime-list"
                  element={
                    <Box>
                      <Typography variant="h6" component="h1" gutterBottom fontWeight="bold">
                        Anime List
                      </Typography>
                      <Typography variant="body2">
                        Your anime list content will appear here.
                      </Typography>
                    </Box>
                  }
                />
                <Route path="lists/manga-list" element={<UserMangaList userData={userData} />} />
                <Route
                  path="statistics"
                  element={<Statistics userData={userData} userId={userData?.id} />}
                />
                <Route
                  path="settings"
                  element={
                    <Box>
                      <Typography variant="h6" component="h1" gutterBottom fontWeight="bold">
                        Settings
                      </Typography>
                      <Typography variant="body2">
                        Your account settings will appear here.
                      </Typography>
                    </Box>
                  }
                />
              </Routes>
            </DashboardCard>
          </Box>
        </Fade>
      </ContentContainer>
    </Box>
  );
};

export default UserPage;
