import React, { useState, useEffect } from "react";
import {
  Box,
  Card,
  CardContent,
  Typography,
  Grid,
  alpha,
  useTheme,
  CircularProgress,
  Divider,
  Tooltip,
  LinearProgress
} from "@mui/material";
import WhatshotIcon from "@mui/icons-material/Whatshot";
import { MOST_CONSUMED_QUERY, fetchFromAniList } from "../../../../queries/queries";
import MovieIcon from "@mui/icons-material/Movie";
import MenuBookIcon from "@mui/icons-material/MenuBook";

/**
 * Most Consumed component that shows the most watched/read anime/manga for a given period
 * Inspired by Last.fm's most listened section
 */
const MostConsumed = ({ userId, mediaType, paperStyles, formatTime }) => {
  const theme = useTheme();
  const [mostConsumedData, setMostConsumedData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [timeframe, setTimeframe] = useState("week"); // Only supporting weekly timeframe
  
  // Get date range for selected timeframe
  const getDateRange = () => {
    const today = new Date();
    const startDate = new Date(today);
    startDate.setDate(today.getDate() - 7);
    
    return {
      startDate: formatDateForApi(startDate),
      endDate: formatDateForApi(today)
    };
  };
  
  // Format a date for the API (YYYYMMDD format for FuzzyDateInt)
  const formatDateForApi = (date) => {
    // AniList's FuzzyDateInt format: YYYYMMDD as an integer value
    return parseInt(
      date.getFullYear() * 10000 + 
      (date.getMonth() + 1) * 100 + 
      date.getDate()
    );
  };
  
  
  useEffect(() => {
    const fetchMostConsumedData = async () => {
      try {
        setLoading(true);
        setError(null);
        
        const dateRange = getDateRange();
        
        // Fetch actual data from the API
        try {
          console.log("Fetching most consumed data with params:", { 
            userId: parseInt(userId), 
            type: mediaType.toUpperCase(),
            startDate: dateRange.startDate,
            endDate: dateRange.endDate
          });
          
          const response = await fetchFromAniList(MOST_CONSUMED_QUERY, { 
            userId: parseInt(userId), 
            type: mediaType.toUpperCase(),
            startDate: dateRange.startDate,
            endDate: dateRange.endDate
          });
          
          console.log("Most consumed API response:", response);
          
          // Process real data from the API response
          if (response && response.Page && response.Page.activities) {
            const activities = response.Page.activities;
            
            // If no activities found, show "no activity" state
            if (activities.length === 0) {
              setMostConsumedData({
                hasActivity: false,
                timeframe
              });
              setLoading(false);
              return;
            }
            
            // Process activities to get most consumed media
            // Group by media ID to count episodes/chapters per series
            const mediaConsumption = {};
            activities.forEach(activity => {
              if (!activity.media) return;
              
              const mediaId = activity.media.id;
              if (!mediaConsumption[mediaId]) {
                mediaConsumption[mediaId] = {
                  id: mediaId,
                  title: activity.media.title.userPreferred,
                  coverImage: activity.media.coverImage,
                  format: activity.media.format,
                  count: 0,
                  minutesWatched: 0,
                  genres: activity.media.genres || [],
                  totalProgress: activity.progress || 0
                };
              }
              
              mediaConsumption[mediaId].count += 1;
              
              // Calculate minutes watched if available (for anime)
              if (mediaType === "anime" && activity.media.duration) {
                mediaConsumption[mediaId].minutesWatched += activity.media.duration;
              }
            });
            
            // Convert to array and sort by count
            const mostConsumedItems = Object.values(mediaConsumption)
              .sort((a, b) => b.count - a.count)
              .slice(0, 5); // Top 5
            
            // Calculate total count
            const totalCount = mostConsumedItems.reduce((sum, item) => sum + item.count, 0);
            
            setMostConsumedData({
              hasActivity: true,
              timeframe,
              mostConsumedItems,
              totalCount
            });
          } else {
            // Fallback to no activity if we can't process the data correctly
            setMostConsumedData({
              hasActivity: false,
              timeframe
            });
          }
          setLoading(false);
        } catch (apiError) {
          console.error("API error:", apiError);
          setError("Failed to fetch your activity data. Please try again later.");
          setLoading(false);
        }
      } catch (err) {
        console.error("Error fetching most consumed data:", err);
        setError(err.message);
        setLoading(false);
      }
    };
    
    fetchMostConsumedData();
  }, [userId, mediaType, timeframe]);
  
  if (loading) {
    return (
      <Card sx={{ ...paperStyles, mb: 3 }}>
        <CardContent sx={{ textAlign: 'center', py: 5 }}>
          <CircularProgress size={40} />
          <Typography variant="body2" sx={{ mt: 2 }}>
            Finding your most consumed {mediaType}...
          </Typography>
        </CardContent>
      </Card>
    );
  }
  
  if (error) {
    return (
      <Card sx={{ ...paperStyles, mb: 3 }}>
        <CardContent>
          <Typography variant="h6" color="error">
            Couldn't load most consumed data
          </Typography>
          <Typography variant="body2">{error}</Typography>
        </CardContent>
      </Card>
    );
  }
  
  if (!mostConsumedData) {
    return (
      <Card sx={{ ...paperStyles, mb: 3 }}>
        <CardContent>
          <Typography variant="h6">No consumption data available</Typography>
          <Typography variant="body2">
            We don't have any data about your most consumed {mediaType}.
          </Typography>
        </CardContent>
      </Card>
    );
  }
  
  // Handle no activity case
  if (!mostConsumedData.hasActivity) {
    return (
      <Card sx={{ ...paperStyles, mb: 3 }}>
        <CardContent>
          <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
            <WhatshotIcon sx={{ color: theme.palette.error.main, mr: 1 }} />
            <Typography variant="h6" sx={{ fontWeight: 600 }}>
              Top {mediaType === "anime" ? "Watched" : "Read"} This Week
            </Typography>
          </Box>
          
          <Box sx={{ 
            py: 4, 
            display: 'flex', 
            flexDirection: 'column', 
            alignItems: 'center',
            justifyContent: 'center' 
          }}>
            <Box sx={{ 
              width: 60, 
              height: 60, 
              borderRadius: '50%', 
              backgroundColor: alpha(theme.palette.text.secondary, 0.1),
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              mb: 2
            }}>
              <WhatshotIcon color="action" sx={{ fontSize: 30 }} />
            </Box>
            <Typography variant="h6" color="text.secondary">
              No activity during this week
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mt: 1, maxWidth: 400, textAlign: 'center' }}>
              You didn't {mediaType === "anime" ? "watch any anime" : "read any manga"} this week.
            </Typography>
          </Box>
        </CardContent>
      </Card>
    );
  }
  
  // Calculate maximum count for normalization
  const maxCount = Math.max(...mostConsumedData.mostConsumedItems.map(item => item.count));
  
  return (
    <Card 
      sx={{ 
        ...paperStyles, 
        mb: 3,
        overflow: 'hidden'
      }}
    >
      <CardContent>
        <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
          <WhatshotIcon sx={{ color: theme.palette.error.main, mr: 1 }} />
          <Typography variant="h6" sx={{ fontWeight: 600 }}>
            Top {mediaType === "anime" ? "Watched" : "Read"} This Week
          </Typography>
        </Box>
        
        <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
          You {mediaType === "anime" ? "watched" : "read"} {mostConsumedData.totalCount} {mediaType === "anime" ? "episodes" : "chapters"} this week
        </Typography>
        
        {mostConsumedData.mostConsumedItems.map((item, index) => (
          <Box key={item.id} sx={{ mb: index < mostConsumedData.mostConsumedItems.length - 1 ? 2 : 0 }}>
            <Grid container spacing={2} alignItems="center">
              {/* Rank */}
              <Grid item xs={1}>
                <Typography 
                  variant="body1" 
                  sx={{ 
                    fontWeight: 'bold',
                    color: index === 0 
                      ? theme.palette.error.main 
                      : index === 1 
                        ? theme.palette.warning.main 
                        : index === 2 
                          ? theme.palette.info.main
                          : 'text.secondary'
                  }}
                >
                  {index + 1}
                </Typography>
              </Grid>
              
              {/* Image */}
              <Grid item xs={2} sm={1}>
                <Box 
                  sx={{ 
                    borderRadius: 1,
                    overflow: 'hidden',
                    width: '100%',
                    paddingTop: '140%',
                    position: 'relative',
                    backgroundColor: alpha(theme.palette.primary.main, 0.1),
                    boxShadow: '0 2px 8px rgba(0,0,0,0.1)'
                  }}
                >
                  {item.coverImage && item.coverImage.medium ? (
                    <Box
                      component="img"
                      src={item.coverImage.medium}
                      alt={item.title}
                      sx={{
                        position: 'absolute',
                        top: 0,
                        left: 0,
                        width: '100%',
                        height: '100%',
                        objectFit: 'cover'
                      }}
                    />
                  ) : (
                    <Box
                      sx={{
                        position: 'absolute',
                        top: 0,
                        left: 0,
                        width: '100%',
                        height: '100%',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        backgroundColor: alpha(theme.palette.text.secondary, 0.1),
                        color: theme.palette.text.secondary
                      }}
                    >
                      {mediaType === "anime" ? <MovieIcon /> : <MenuBookIcon />}
                    </Box>
                  )}
                </Box>
              </Grid>
              
              {/* Details */}
              <Grid item xs={9} sm={7}>
                <Tooltip title={item.title}>
                  <Typography 
                    variant="subtitle2" 
                    sx={{ 
                      fontWeight: 'bold',
                      overflow: 'hidden',
                      textOverflow: 'ellipsis',
                      display: '-webkit-box',
                      WebkitLineClamp: 1,
                      WebkitBoxOrient: 'vertical'
                    }}
                  >
                    {item.title}
                  </Typography>
                </Tooltip>
                
                <Box sx={{ display: 'flex', alignItems: 'center' }}>
                  <Typography 
                    variant="caption" 
                    color="text.secondary"
                    sx={{ mr: 1 }}
                  >
                    {item.format || "Unknown"}
                  </Typography>
                  
                  {item.genres && item.genres.slice(0, 2).map((genre, i) => (
                    <Typography 
                      key={genre}
                      variant="caption" 
                      sx={{ 
                        px: 0.8,
                        py: 0.2,
                        borderRadius: 10,
                        backgroundColor: alpha(i === 0 ? theme.palette.primary.main : theme.palette.secondary.main, 0.1),
                        color: i === 0 ? theme.palette.primary.main : theme.palette.secondary.main,
                        fontSize: '0.65rem',
                        fontWeight: 'medium',
                        mr: 0.5
                      }}
                    >
                      {genre}
                    </Typography>
                  ))}
                </Box>
              </Grid>
              
              {/* Count */}
              <Grid item xs={12} sm={3}>
                <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'flex-end' }}>
                  <Typography 
                    variant="body2" 
                    sx={{ 
                      fontWeight: 'bold',
                      color: theme.palette.primary.main
                    }}
                  >
                    {item.count}
                  </Typography>
                  <Typography 
                    variant="caption" 
                    color="text.secondary"
                    sx={{ ml: 0.5 }}
                  >
                    {mediaType === "anime" ? "eps" : "ch"}
                  </Typography>
                </Box>
                
                <Tooltip 
                  title={
                    mediaType === "anime" 
                      ? `${formatTime(item.minutesWatched)} watched this week (${item.totalProgress} episodes total)` 
                      : `${item.count} chapters read this week (${item.totalProgress} chapters total)`
                  }
                >
                  <LinearProgress 
                    variant="determinate" 
                    value={(item.count / maxCount) * 100} 
                    sx={{ 
                      height: 4,
                      mt: 0.5,
                      borderRadius: 2,
                      backgroundColor: alpha(theme.palette.primary.main, 0.1),
                      '& .MuiLinearProgress-bar': {
                        backgroundColor: index === 0 
                          ? theme.palette.error.main 
                          : index === 1 
                            ? theme.palette.warning.main 
                            : theme.palette.primary.main
                      }
                    }} 
                  />
                </Tooltip>
              </Grid>
            </Grid>
            
            {index < mostConsumedData.mostConsumedItems.length - 1 && (
              <Divider sx={{ my: 1.5 }} />
            )}
          </Box>
        ))}
      </CardContent>
    </Card>
  );
};

export default MostConsumed;
