import React, { useMemo } from "react";
import {
  Box,
  Card,
  CardContent,
  Typography,
  Divider,
  Grid,
  alpha,
  useTheme,
  Tooltip,
  LinearProgress
} from "@mui/material";
import AutoGraphIcon from "@mui/icons-material/AutoGraph";
import LocalFireDepartmentIcon from "@mui/icons-material/LocalFireDepartment";
import ScheduleIcon from "@mui/icons-material/Schedule";
import TrendingUpIcon from "@mui/icons-material/TrendingUp";
import EmojiEventsIcon from "@mui/icons-material/EmojiEvents";

/**
 * Quick Facts component that displays interesting statistics about the user's anime/manga habits
 * Inspired by Last.fm's statistics
 */
const QuickFacts = ({ stats, mediaType, paperStyles, formatTime }) => {
  const theme = useTheme();
  
  // Generate facts based on user's statistics
  const facts = useMemo(() => {
    if (!stats || !stats[mediaType]) return [];
    
    const currentStats = stats[mediaType];
    const facts = [];
    
    // Calculate average consumption per day
    const minutesPerDay = currentStats.minutesWatched 
      ? Math.round(currentStats.minutesWatched / 365) 
      : null;
      
    const chaptersPerDay = currentStats.chaptersRead 
      ? Math.round(currentStats.chaptersRead / 365 * 10) / 10
      : null;
    
    // Calculate average rating
    const avgScore = currentStats.meanScore 
      ? currentStats.meanScore.toFixed(1) 
      : null;
    
    // Get favorite genres
    const topGenres = currentStats.genres 
      ? [...currentStats.genres].sort((a, b) => b.count - a.count).slice(0, 3)
      : [];
    
    // Get most watched year
    const mostWatchedYear = currentStats.releaseYears 
      ? [...currentStats.releaseYears].sort((a, b) => b.count - a.count)[0]
      : null;
    
    // Calculate completion rate
    const completed = currentStats.statuses?.find(s => s.status === "COMPLETED")?.count || 0;
    const total = currentStats.count || 0;
    const completionRate = total ? Math.round((completed / total) * 100) : 0;
    
    // Generate interesting facts
    if (mediaType === "anime") {
      if (minutesPerDay !== null) {
        facts.push({
          icon: <ScheduleIcon />,
          color: theme.palette.info.main,
          title: "Daily Dose",
          value: `${minutesPerDay} min`,
          description: `You watch about ${minutesPerDay} minutes of anime per day on average`
        });
      }
      
      if (currentStats.episodesWatched) {
        facts.push({
          icon: <AutoGraphIcon />,
          color: theme.palette.success.main,
          title: "Marathon Potential",
          value: `${Math.round(currentStats.episodesWatched / 12)} series`,
          description: `If all anime were 12 episodes, you've completed the equivalent of ${Math.round(currentStats.episodesWatched / 12)} series`
        });
      }
    } else {
      // Manga facts
      if (chaptersPerDay !== null) {
        facts.push({
          icon: <ScheduleIcon />,
          color: theme.palette.info.main,
          title: "Daily Pages",
          value: `${chaptersPerDay} ch`,
          description: `You read about ${chaptersPerDay} chapters of manga per day on average`
        });
      }
      
      if (currentStats.volumesRead) {
        facts.push({
          icon: <AutoGraphIcon />,
          color: theme.palette.success.main,
          title: "Bookshelf Size",
          value: `${currentStats.volumesRead} vols`,
          description: `Your manga collection would take up ${currentStats.volumesRead} volumes on a bookshelf`
        });
      }
    }
    
    // Facts for both anime and manga
    if (avgScore) {
      facts.push({
        icon: <EmojiEventsIcon />,
        color: theme.palette.warning.main,
        title: "Rating Habits",
        value: avgScore,
        description: `Your average rating is ${avgScore}/10, which makes you a ${parseFloat(avgScore) > 7.5 ? 'generous' : 'critical'} rater`
      });
    }
    
    if (mostWatchedYear) {
      facts.push({
        icon: <TrendingUpIcon />,
        color: theme.palette.error.main,
        title: "Favorite Era",
        value: mostWatchedYear.releaseYear,
        description: `Your most watched year is ${mostWatchedYear.releaseYear} with ${mostWatchedYear.count} ${mediaType}`
      });
    }
    
    if (topGenres.length > 0) {
      facts.push({
        icon: <LocalFireDepartmentIcon />,
        color: theme.palette.secondary.main,
        title: "Genre Affinity",
        value: topGenres[0].genre,
        description: `You strongly prefer ${topGenres[0].genre}, ${topGenres[1]?.genre || ''} ${topGenres[2] ? `and ${topGenres[2].genre}` : ''}`
      });
    }
    
    // Completion fact
    facts.push({
      icon: <AutoGraphIcon />,
      color: theme.palette.primary.main,
      title: "Completion Rate",
      value: `${completionRate}%`,
      progressValue: completionRate,
      description: `You complete ${completionRate}% of the ${mediaType} you start`
    });
    
    return facts;
  }, [stats, mediaType, theme, formatTime]);
  
  if (!stats || !stats[mediaType] || facts.length === 0) {
    return (
      <Card sx={{ ...paperStyles, mb: 3 }}>
        <CardContent>
          <Typography variant="h6">Quick Facts</Typography>
          <Typography variant="body2" color="text.secondary">
            Not enough data to generate interesting facts.
          </Typography>
        </CardContent>
      </Card>
    );
  }
  
  return (
    <Card 
      sx={{ 
        ...paperStyles, 
        mb: 3,
        overflow: 'hidden',
        transition: 'transform 0.3s ease, box-shadow 0.3s ease',
        '&:hover': {
          boxShadow: 6
        }
      }}
    >
      <CardContent>
        <Typography variant="h6" sx={{ fontWeight: 600, mb: 1 }}>
          Quick Facts
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
          Interesting insights about your {mediaType} habits
        </Typography>
        
        <Grid container spacing={3}>
          {facts.slice(0, 6).map((fact, index) => (
            <Grid item xs={12} sm={6} md={4} key={fact.title}>
              <Tooltip title={fact.description}>
                <Box 
                  sx={{ 
                    p: 2, 
                    borderRadius: 2,
                    border: `1px solid ${alpha(fact.color, 0.3)}`,
                    backgroundColor: alpha(fact.color, 0.05),
                    transition: 'all 0.2s ease',
                    height: '100%',
                    '&:hover': {
                      backgroundColor: alpha(fact.color, 0.1),
                      transform: 'translateY(-2px)'
                    }
                  }}
                >
                  <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                    <Box 
                      sx={{ 
                        color: fact.color,
                        mr: 1,
                        display: 'flex',
                        alignItems: 'center'
                      }}
                    >
                      {fact.icon}
                    </Box>
                    <Typography variant="subtitle2" color="text.secondary">
                      {fact.title}
                    </Typography>
                  </Box>
                  
                  <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 1, color: fact.color }}>
                    {fact.value}
                  </Typography>
                  
                  {fact.progressValue && (
                    <LinearProgress 
                      variant="determinate" 
                      value={fact.progressValue} 
                      sx={{ 
                        height: 6, 
                        borderRadius: 3,
                        backgroundColor: alpha(fact.color, 0.2),
                        '& .MuiLinearProgress-bar': {
                          backgroundColor: fact.color
                        }
                      }} 
                    />
                  )}
                </Box>
              </Tooltip>
            </Grid>
          ))}
        </Grid>
      </CardContent>
    </Card>
  );
};

export default QuickFacts;
