// src/styles/themes.js
import { createTheme, alpha } from "@mui/material/styles";

// Common typography settings (can be overridden as needed)
const baseTypography = {
  h1: { fontSize: "4rem", fontWeight: 500, lineHeight: 1.2 },
  h6: { fontWeight: 500 },
  button: { textTransform: "none" },
};

/**
 * Utility to create a custom theme.
 *
 * @param {object} options
 * @param {object} options.palette - The palette configuration.
 * @param {object} options.typography - The typography configuration.
 * @param {string} options.baselineBg - The global body background color.
 * @param {string} options.baselineText - The global body text color.
 */
const createCustomTheme = ({ palette, typography, baselineBg, baselineText }) =>
  createTheme({
    palette,
    typography,
    components: {
      MuiCssBaseline: {
        styleOverrides: {
          body: {
            backgroundColor: baselineBg,
            color: baselineText,
            transition: "background-color 0.3s ease, color 0.3s ease",
          },
        },
      },
    },
  });

/**
 * Augments the provided theme with transparent colors.
 *
 * @param {object} theme - The theme returned from createCustomTheme.
 * @param {number} transparency - A value between 0 and 1 to set the opacity.
 * @returns {object} - A new theme with additional transparent colors.
 */
const withTransparentColors = (theme, transparency = 0.5) => {
  return createTheme({
    ...theme,
    palette: {
      ...theme.palette,
      // Add custom transparent colors based on existing palette values
      transparentPrimary: alpha(theme.palette.primary.main, transparency),
      transparentSecondary: alpha(theme.palette.secondary.main, transparency),
      transparentBackground: alpha(theme.palette.background.default, transparency),
      transparentPaper: alpha(theme.palette.background.paper, transparency),
    },
  });
};

// Light Theme
export const lightTheme = withTransparentColors(
  createCustomTheme({
    palette: {
      primary: { main: "#ff3b6c" }, // Brighter red
      secondary: { main: "#ff758c" }, // Softer pink
      background: { default: "#F8F8F8", paper: "#f5f5f5" },
      text: { primary: "#1f1f1f", secondary: "#757575" }, 
    },
    typography: {
      fontFamily: "'Overpass', Arial, sans-serif",
      ...baseTypography,
      h1: {
        ...baseTypography.h1,
        fontWeight: 900, // Bold for impact
        letterSpacing: "-0.03em", // Tight letter spacing
      },
      button: {
        ...baseTypography.button,
        fontWeight: 600, // Slightly bolder buttons
        letterSpacing: "0.03em", // Slightly spaced letters
      },
    },
    baselineBg: "#F8F8F8",
    baselineText: "#1f1f1f",
  })
);

// Dark Theme
export const darkTheme = withTransparentColors(
  createCustomTheme({
    palette: {
      mode: "dark", // add this line
      primary: { main: "#ff3b6c" },
      secondary: { main: "#ff758c" },
      background: { default: "#121212", paper: "#1e1e1e" },
      text: { primary: "#f5f5f5", secondary: "#bdbdbd" },
    },
    typography: {
      fontFamily: "'Overpass', Arial, sans-serif",
      ...baseTypography,
      h1: {
        ...baseTypography.h1,
        fontWeight: 900,
        letterSpacing: "-0.03em",
      },
      button: {
        ...baseTypography.button,
        fontWeight: 600,
        letterSpacing: "0.03em",
      },
    },
    baselineBg: "#121212",
    baselineText: "#f5f5f5",
  })
);



// Starpeggio Theme
export const starpeggioTheme = withTransparentColors(
  createCustomTheme({
    palette: {
      primary: { main: "#3945ff" },
      secondary: { main: "#000000" },
      background: { default: "#e8ecf2", paper: "#dfe3ea" },
      text: { primary: "#3945ff", secondary: "#000000" },
    },
    typography: {
      fontFamily: "'PP Neue Montreal', sans-serif",
      ...baseTypography,
    },
    baselineBg: "#e8ecf2",
    baselineText: "#3945ff",
  })
);


// Update themes export
export const themes = {
  light: lightTheme,
  dark: darkTheme,
  starpeggio: starpeggioTheme,
};