// hooks/useAniListData.js
import { useState, useCallback, useMemo, useEffect } from 'react';
import axios from 'axios';
import { useLocalStorage } from './useLocalStorage';

const CACHE = new Map();
const CACHE_DURATION = 5 * 60 * 1000; // 5 minutes

const buildQuery = (mediaType) => `query ($username: String!) {
  MediaListCollection(userName: $username, type: ${mediaType}) {
    lists {
      entries {
        id
        score
        progress
        status
        media {
          id
          coverImage { large }
          title { romaji english }
          description
          tags { name rank }
          genres
          ${mediaType === 'ANIME' ? 'episodes' : 'chapters'}
          siteUrl
        }
        startedAt { year month day }
        completedAt { year month day }
      }
    }
  }
}`;

const processResponse = (response, mediaType) => {
  const lists = response?.data?.data?.MediaListCollection?.lists;
  if (!lists?.length) throw new Error('NO_LIST_FOUND');
  return lists.flatMap(list => list.entries);
};

const calculateGenres = (entries) => {
  const genreMap = new Map();
  entries.forEach(({ media }) => {
    media.genres?.forEach(genre => {
      genreMap.set(genre, (genreMap.get(genre) || 0) + 1);
    });
  });
  return Array.from(genreMap.entries())
    .map(([genre, count]) => ({ genre, count }))
    .sort((a, b) => b.count - a.count);
};

export const useAniListData = (username, mediaType) => {
  const [state, setState] = useState({
    mediaList: [],
    loading: false,
    error: null,
    genresWithCount: []
  });

  const fetchData = useCallback(async () => {
    if (!username?.trim()) return;

    const cacheKey = `${username}:${mediaType}`;
    const cached = CACHE.get(cacheKey);

    if (cached && Date.now() - cached.timestamp < CACHE_DURATION) {
      setState(cached.data);
      return;
    }

    setState(prev => ({ ...prev, loading: true, error: null }));

    try {
      const source = axios.CancelToken.source();
      const timeout = setTimeout(() => source.cancel(), 10000);

      const response = await axios.post(
        'https://graphql.anilist.co',
        {
          query: buildQuery(mediaType),
          variables: { username }
        },
        { cancelToken: source.token }
      );

      clearTimeout(timeout);

      if (response.data.errors) {
        throw new Error(response.data.errors[0]?.message || 'API_ERROR');
      }

      const entries = processResponse(response, mediaType);
      const genresWithCount = calculateGenres(entries);

      const newState = {
        mediaList: entries,
        genresWithCount,
        loading: false,
        error: null
      };

      CACHE.set(cacheKey, {
        timestamp: Date.now(),
        data: newState
      });

      setState(newState);
    } catch (error) {
      if (axios.isCancel(error)) return;

      const errorMessage = error.message === 'NO_LIST_FOUND'
        ? `No ${mediaType.toLowerCase()} list found for user`
        : error.response?.data?.errors?.[0]?.message || 
          error.message || 'Failed to fetch data';

      setState(prev => ({
        ...prev,
        loading: false,
        error: errorMessage
      }));
    }
  }, [username, mediaType]);

  // Auto-refresh when parameters change
  useEffect(() => {
    fetchData();
  }, [fetchData]);

  return useMemo(() => ({
    ...state,
    fetchData
  }), [state, fetchData]);
};