import React, { useState, useEffect, useRef, useCallback, useMemo } from "react";
import {
  Box,
  Typography,
  Avatar,
  Divider,
  Collapse,
  Tooltip,
  IconButton,
  useTheme,
  alpha,
} from "@mui/material";
import { styled } from "@mui/material/styles";
import {
  Dashboard as DashboardIcon,
  ListAlt as ListAltIcon,
  BarChart as BarChartIcon,
  Settings as SettingsIcon,
  Movie as MovieIcon,
  MenuBook as MenuBookIcon,
  ExpandMore as ExpandMoreIcon,
  ExpandLess as ExpandLessIcon,
  ChevronLeft as ChevronLeftIcon,
  ChevronRight as ChevronRightIcon,
  SwapHoriz as SwapHorizIcon,
} from "@mui/icons-material";
import { Link as RouterLink, useNavigate } from "react-router-dom";

// Unified animation constants
const ANIMATION_DURATION = "0.3s";
const ANIMATION_TIMING = "cubic-bezier(0.4, 0, 0.2, 1)";

// Styled components with improved aesthetics and scroll behavior
// Matched the transition timing with header component (all 0.3s ease)
const SidebarContainer = styled(Box)(
  ({ theme, sidebarOpen, showSidebar }) => ({
    position: "fixed",
    left: 0,
    top: 64,
    bottom: 0,
    height: "calc(100vh + 64px)",
    minHeight: "calc(100% + 64px)",
    backgroundColor:
      theme.palette.mode === "dark"
        ? alpha(theme.palette.grey[900], 0.95)
        : alpha(theme.palette.primary.dark, 0.95),
    backdropFilter: "blur(8px)",
    color: theme.palette.common.white,
    overflowY: "auto",
    overflowX: "hidden",
    zIndex: theme.zIndex.drawer + 1, // Lower than header
    transition: `all ${ANIMATION_DURATION} ${ANIMATION_TIMING}`,
    boxShadow: sidebarOpen ? theme.shadows[8] : "none",
    transform: `translateY(${showSidebar ? "0" : "-64px"}) ${!sidebarOpen ? "translateX(-100%)" : ""}`,
    borderRight: `1px solid ${alpha(theme.palette.common.white, 0.05)}`,
    "&::-webkit-scrollbar": {
      width: 4,
    },
    "&::-webkit-scrollbar-track": {
      backgroundColor: "transparent",
    },
    "&::-webkit-scrollbar-thumb": {
      backgroundColor: alpha(theme.palette.common.white, 0.15),
      borderRadius: 10,
      "&:hover": {
        backgroundColor: alpha(theme.palette.common.white, 0.25),
      },
    },
  })
);

// Improved toggle button styling and positioning with scroll behavior
// Matched transition timing with header
const SidebarToggle = styled(IconButton)(
  ({ theme, sidebarOpen, showSidebar }) => ({
    position: "fixed",
    left: sidebarOpen ? 246 : 6,
    top: 76, // Fixed initial position
    zIndex: theme.zIndex.drawer + 2, // Same as header
    background:
      theme.palette.mode === "dark"
        ? alpha(theme.palette.grey[800], 0.85)
        : alpha(theme.palette.primary.main, 0.85),
    backdropFilter: "blur(5px)",
    color: theme.palette.common.white,
    transition: `all ${ANIMATION_DURATION} ${ANIMATION_TIMING}`,
    padding: 6,
    boxShadow: theme.shadows[3],
    border: `1px solid ${alpha(theme.palette.common.white, 0.1)}`,
    transform: `translateY(${showSidebar ? "0" : "-64px"})`,
    "&:hover": {
      background:
        theme.palette.mode === "dark"
          ? alpha(theme.palette.grey[700], 0.9)
          : alpha(theme.palette.primary.dark, 0.9),
      transform: `translateY(${showSidebar ? "0" : "-64px"}) scale(1.05)`,
    },
    "&::after": {
      content: '""',
      position: "absolute",
      top: -14,
      bottom: -14,
      left: sidebarOpen ? -6 : -16,
      right: -10,
      zIndex: -1,
    },
  })
);

// Enhanced banner with parallax-like effect
const BannerContainer = styled(Box)(({ theme }) => ({
  position: "relative",
  width: "100%",
  height: 110,
  overflow: "visible", // Changed from "hidden" to allow avatar to overflow
  marginBottom: theme.spacing(5),
  zIndex: 2,
}));

const BannerImage = styled("div")(({ theme, image }) => ({
  position: "absolute",
  top: 0,
  left: 0,
  width: "100%",
  height: "100%",
  backgroundImage: `url(${image})`,
  backgroundSize: "cover",
  backgroundPosition: "center",
  transform: "scale(1.05)",
  "&::after": {
    content: '""',
    position: "absolute",
    top: 0,
    left: 0,
    width: "100%",
    height: "100%",
    background:
      theme.palette.mode === "dark"
        ? `linear-gradient(to bottom, ${alpha(
            theme.palette.grey[900],
            0
          )} 0%, ${alpha(theme.palette.grey[900], 0.7)} 70%, ${alpha(
            theme.palette.grey[900],
            0.95
          )} 100%)`
        : `linear-gradient(to bottom, ${alpha(
            theme.palette.primary.dark,
            0
          )} 0%, ${alpha(theme.palette.primary.dark, 0.7)} 70%, ${alpha(
            theme.palette.primary.dark,
            0.95
          )} 100%)`,
    zIndex: 1,
  },
}));

// Enhanced avatar styling with proper clickable behavior
const AvatarWrapper = styled(RouterLink)(({ theme }) => ({
  position: "absolute",
  bottom: -38,
  left: "50%",
  transform: "translateX(-50%)",
  zIndex: 100, // Increased z-index to ensure it's above other elements
  textDecoration: "none",
  display: "block",
  width: 76,
  height: 76,
  borderRadius: "50%",
  "&:focus": {
    outline: `2px solid ${theme.palette.secondary.main}`,
    outlineOffset: 2,
  },
  "&:focus:not(:focus-visible)": {
    outline: "none",
  },
}));

const ProfileAvatar = styled(Avatar)(({ theme }) => ({
  width: "100%",
  height: "100%",
  border: `3px solid ${
    theme.palette.mode === "dark"
      ? alpha(theme.palette.grey[900], 0.8)
      : alpha(theme.palette.primary.dark, 0.8)
  }`,
  boxShadow: `0 4px 20px ${alpha(theme.palette.common.black, 0.3)}`,
  transition: "all 0.3s ease", // Matched with header transition
  "&:hover": {
    transform: "scale(1.05)",
    boxShadow: `0 8px 24px ${alpha(theme.palette.common.black, 0.4)}`,
  },
}));

// Improved stats box with subtle animations and toggle capability
const StatBox = styled(Box)(({ theme }) => ({
  display: "flex",
  justifyContent: "space-around",
  alignItems: "center",
  width: "90%",
  margin: "0 auto",
  marginTop: theme.spacing(1.5),
  marginBottom: theme.spacing(1.5),
  background: alpha(theme.palette.common.white, 0.06),
  backdropFilter: "blur(10px)",
  borderRadius: theme.shape.borderRadius * 2,
  padding: theme.spacing(1.5, 1),
  border: `1px solid ${alpha(theme.palette.common.white, 0.08)}`,
  boxShadow: `0 4px 12px ${alpha(theme.palette.common.black, 0.1)}`,
  transition: "all 0.3s ease", // Matched with header transition
  cursor: "pointer",
  "&:hover": {
    transform: "translateY(-2px)",
    boxShadow: `0 6px 16px ${alpha(theme.palette.common.black, 0.15)}`,
    background: alpha(theme.palette.common.white, 0.09),
  },
  position: "relative",
  zIndex: 3, // Lower than the avatar
}));

const StatToggleButton = styled(IconButton)(({ theme }) => ({
  position: "absolute",
  right: 3,
  top: "50%",
  transform: "translateY(-50%)",
  color: alpha(theme.palette.common.white, 0.5),
  padding: 4,
  transition: "all 0.2s ease", // Slightly faster for responsive feel
  "&:hover": {
    color: theme.palette.common.white,
    background: alpha(theme.palette.common.white, 0.1),
  },
}));

// Enhanced navigation links with better hover effects
const NavLink = styled(RouterLink)(({ theme, active }) => ({
  display: "flex",
  alignItems: "center",
  gap: theme.spacing(1.5),
  padding: theme.spacing(1.3, 2),
  marginBottom: theme.spacing(0.7),
  borderRadius: theme.shape.borderRadius * 1.5,
  color: active
    ? theme.palette.common.white
    : alpha(theme.palette.common.white, 0.78),
  backgroundColor: active
    ? alpha(theme.palette.common.white, 0.1)
    : "transparent",
  textDecoration: "none",
  transition: "all 0.3s ease", // Matched with header transition
  position: "relative",
  marginLeft: theme.spacing(1),
  marginRight: theme.spacing(1),
  "&::before": active
    ? {
        content: '""',
        position: "absolute",
        left: 0,
        top: "50%",
        transform: "translateY(-50%)",
        width: 3,
        height: "60%",
        backgroundColor: theme.palette.secondary.main,
        borderRadius: "0 4px 4px 0",
      }
    : {},
  "&:hover": {
    background: alpha(theme.palette.common.white, 0.12),
    transform: "translateX(3px)",
    color: theme.palette.common.white,
  },
}));

// Improved dropdown category styling
const NavExpander = styled(Box)(({ theme, isExpanded }) => ({
  display: "flex",
  alignItems: "center",
  justifyContent: "space-between",
  padding: theme.spacing(1.3, 2),
  marginBottom: theme.spacing(0.7),
  borderRadius: theme.shape.borderRadius * 1.5,
  color: isExpanded
    ? theme.palette.common.white
    : alpha(theme.palette.common.white, 0.78),
  backgroundColor: isExpanded
    ? alpha(theme.palette.common.white, 0.1)
    : "transparent",
  cursor: "pointer",
  transition: "all 0.3s ease", // Matched with header transition
  marginLeft: theme.spacing(1),
  marginRight: theme.spacing(1),
  "&:hover": {
    background: alpha(theme.palette.common.white, 0.12),
    transform: "translateX(3px)",
    color: theme.palette.common.white,
  },
}));

// Extra content to ensure sidebar has enough height when scrolled
const ExtendedFooter = styled(Box)(({ theme }) => ({
  width: "100%",
  minHeight: "150px", // Add extra space at the bottom
  padding: theme.spacing(2),
  opacity: 0.5,
  
}));

const UserSidebar = ({
  userData,
  myListsExpanded,
  toggleMyLists,
  isRouteActive,
  sidebarOpen: initialSidebarOpen = true,
}) => {
  const theme = useTheme();
  const navigate = useNavigate();

  // State for controlling sidebar visibility
  const [sidebarOpen, setSidebarOpen] = useState(initialSidebarOpen);

  // State for tracking scroll - simplified to match header behavior
  const [showSidebar, setShowSidebar] = useState(true);
  const [scrollPosition, setScrollPosition] = useState(0);

  // Get stored stats preference from localStorage or default to manga
  const [showMangaStats, setShowMangaStats] = useState(() => {
    const stored = localStorage.getItem("userStatsPreference");
    return stored ? stored === "manga" : true;
  });

  // Smooth transition for stats change
  const [statFadeOut, setStatFadeOut] = useState(false);

  // Handle window resize for responsive behavior
  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth < 600 && sidebarOpen) {
        setSidebarOpen(false);
      }
    };

    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, [sidebarOpen]);

  // Scroll handler - synced with header behavior
  const handleScroll = useCallback(() => {
    const currentScrollPos = window.scrollY;
    const isScrollingUp = currentScrollPos < scrollPosition;
    
    // Immediate update without threshold
    setShowSidebar(isScrollingUp);
    setScrollPosition(currentScrollPos);
  }, [scrollPosition]);

  // Add passive scroll listener for better performance
  useEffect(() => {
    const options = { passive: true };
    window.addEventListener("scroll", handleScroll, options);
    return () => window.removeEventListener("scroll", handleScroll, options);
  }, [handleScroll]);

  // Function to toggle sidebar visibility
  const toggleSidebar = useCallback(() => {
    setSidebarOpen(prevState => !prevState);
  }, []);

  // Function to navigate to user profile
  const handleProfileClick = useCallback((e) => {
    // If a direct link is provided through RouterLink, this function can add extra behavior
    console.log(`Navigating to ${userData.name}'s profile`);
  }, [userData.name]);

  // Function to toggle between manga and anime stats
  const toggleStats = useCallback(() => {
    setStatFadeOut(true);
    setTimeout(() => {
      setShowMangaStats(prevState => {
        // Save preference to localStorage
        localStorage.setItem(
          "userStatsPreference",
          !prevState ? "manga" : "anime"
        );
        return !prevState;
      });
      setStatFadeOut(false);
    }, 300);
  }, []);

  // Default banner if user doesn't have one - memoized
  const userBanner = useMemo(() => 
    userData.bannerImage ||
    "https://s4.anilist.co/file/anilistcdn/user/banner/b452284-UJ8ptMVcnYXl.jpg",
  [userData.bannerImage]);

  // Memoize sidebar drawer content to prevent unnecessary re-renders
  const drawerContent = useMemo(() => (
    <Box
      sx={{
        px: 2,
        pb: 3,
        mt: 2, // Added margin top to ensure content doesn't overlay the avatar
        position: "relative",
        zIndex: 2, // Lower than avatar to prevent overlapping
      }}
    >
      {/* Username centered below avatar */}
      <Box sx={{ textAlign: "center" }}>
        <Typography
          variant="subtitle1"
          fontWeight="600"
          aria-label={`Username: ${userData.name}`}
          sx={{
            color: "white",
            mb: 0.5,
            fontSize: "1.1rem",
            letterSpacing: "0.01em",
            mt: 1, // Added margin to create space after avatar
          }}
        >
          {userData.name}
        </Typography>

        {/* Improved stats display with toggle capability */}
        <StatBox
          onClick={toggleStats}
          role="button"
          aria-label="Toggle between manga and anime statistics"
        >
          <Box
            sx={{
              display: "flex",
              width: "100%",
              justifyContent: "space-around",
              opacity: statFadeOut ? 0 : 1,
              transition: "opacity 0.3s ease",
            }}
          >
            <Box sx={{ textAlign: "center", flex: 1 }}>
              <Typography
                variant="caption"
                sx={{
                  color: alpha(theme.palette.common.white, 0.7),
                  display: "block",
                  fontWeight: 500,
                  fontSize: "0.7rem",
                  letterSpacing: "0.05em",
                  textTransform: "uppercase",
                }}
              >
                Series
              </Typography>
              <Typography
                variant="body2"
                fontWeight="600"
                sx={{
                  color: "white",
                  fontSize: "0.95rem",
                }}
              >
                {showMangaStats
                  ? userData.statistics.manga.count.toLocaleString()
                  : userData.statistics.anime.count.toLocaleString()}
              </Typography>
            </Box>
            <Box sx={{ textAlign: "center", flex: 1 }}>
              <Typography
                variant="caption"
                sx={{
                  color: alpha(theme.palette.common.white, 0.7),
                  display: "block",
                  fontWeight: 500,
                  fontSize: "0.7rem",
                  letterSpacing: "0.05em",
                  textTransform: "uppercase",
                }}
              >
                {showMangaStats ? "Chapters" : "Hours"}
              </Typography>
              <Typography
                variant="body2"
                fontWeight="600"
                sx={{
                  color: "white",
                  fontSize: "0.95rem",
                }}
              >
                {showMangaStats
                  ? userData.statistics.manga.chaptersRead.toLocaleString()
                  : userData.statistics.anime.minutesWatched
                  ? Math.round(
                      userData.statistics.anime.minutesWatched / 60
                    ).toLocaleString()
                  : "0"}
              </Typography>
            </Box>
          </Box>
          
       
        </StatBox>
      </Box>

      <Divider
        sx={{
          borderColor: alpha(theme.palette.common.white, 0.08),
          width: "80%",
          margin: "0 auto",
          mb: 2.5,
          mt: 1.5,
        }}
      />

      <Box
        component="nav"
        aria-label="Main navigation"
        sx={{ display: "flex", flexDirection: "column"}}
      >
        <NavLink
          to="/user/overview"
          active={isRouteActive("/user/overview") ? 1 : 0}
          aria-current={
            isRouteActive("/user/overview") ? "page" : undefined
          }
        >
          <DashboardIcon sx={{ fontSize: "1.2rem" }} />
          <Typography variant="body2" fontWeight={500}>
            Overview
          </Typography>
        </NavLink>

        <NavExpander
          isExpanded={myListsExpanded}
          onClick={toggleMyLists}
          tabIndex={0}
          role="button"
          aria-expanded={myListsExpanded}
          aria-controls="lists-menu"
          onKeyDown={(e) => {
            if (e.key === "Enter" || e.key === " ") {
              e.preventDefault();
              toggleMyLists();
            }
          }}
        >
          <Box sx={{ display: "flex", alignItems: "center", gap: 1.5 }}>
            <ListAltIcon sx={{ fontSize: "1.2rem" }} />
            <Typography variant="body2" fontWeight={500}>
              My Lists
            </Typography>
          </Box>
          {myListsExpanded ? (
            <ExpandLessIcon sx={{ fontSize: "1.1rem" }} />
          ) : (
            <ExpandMoreIcon sx={{ fontSize: "1.1rem" }} />
          )}
        </NavExpander>

        <Collapse in={myListsExpanded} id="lists-menu">
          <Box
            sx={{
              pl: 1.5,
              ml: 2.5,
              borderLeft: `1px solid ${alpha(
                theme.palette.common.white,
                0.15
              )}`,
              mb: 1,
              mt: 0.5,
            }}
          >
            <NavLink
              to="/user/lists/anime-list"
              active={isRouteActive("/user/lists/anime-list") ? 1 : 0}
              aria-current={
                isRouteActive("/user/lists/anime-list") ? "page" : undefined
              }
              sx={{ py: 0.9, px: 1.5 }}
            >
              <MovieIcon sx={{ fontSize: "1.1rem" }} />
              <Typography variant="body2">Anime List</Typography>
            </NavLink>

            <NavLink
              to="/user/lists/manga-list"
              active={isRouteActive("/user/lists/manga-list") ? 1 : 0}
              aria-current={
                isRouteActive("/user/lists/manga-list") ? "page" : undefined
              }
              sx={{ py: 0.9, px: 1.5 }}
            >
              <MenuBookIcon sx={{ fontSize: "1.1rem" }} />
              <Typography variant="body2">Manga List</Typography>
            </NavLink>
          </Box>
        </Collapse>

        <NavLink
          to="/user/statistics"
          active={isRouteActive("/user/statistics") ? 1 : 0}
          aria-current={
            isRouteActive("/user/statistics") ? "page" : undefined
          }
        >
          <BarChartIcon sx={{ fontSize: "1.2rem" }} />
          <Typography variant="body2" fontWeight={500}>
            Statistics
          </Typography>
        </NavLink>

        <Divider
          sx={{
            borderColor: alpha(theme.palette.common.white, 0.08),
            width: "80%",
            margin: "1.5rem auto",
          }}
        />

        <NavLink
          to="/user/settings"
          active={isRouteActive("/user/settings") ? 1 : 0}
          aria-current={
            isRouteActive("/user/settings") ? "page" : undefined
          }
        >
          <SettingsIcon sx={{ fontSize: "1.2rem" }} />
          <Typography variant="body2" fontWeight={500}>
            Settings
          </Typography>
        </NavLink>

        {/* Enhanced footer info */}
        <Box
          sx={{
            mt: "auto",
            pt: 6,
            pb: 2,
            opacity: 0.6,
            textAlign: "center",
          }}
        >
          <Typography
            variant="caption"
            sx={{
              color: alpha(theme.palette.common.white, 0.6),
              display: "block",
              fontSize: "0.7rem",
              letterSpacing: "0.03em",
            }}
          >
            Last login: Today
          </Typography>
        </Box>
        
        {/* Extended footer to ensure enough content when sidebar moves up */}
        <ExtendedFooter>
          <Typography
            variant="caption"
            sx={{
              color: alpha(theme.palette.common.white, 0.4),
              display: "block",
              fontSize: "0.65rem",
              textAlign: "center",
            }}
          >
            tsubaki v1.2.5
          </Typography>
        </ExtendedFooter>
      </Box>
    </Box>
  ), [
    userData.name, 
    userData.statistics, 
    theme, 
    showMangaStats, 
    statFadeOut, 
    toggleStats, 
    isRouteActive, 
    myListsExpanded, 
    toggleMyLists
  ]);

  return (
    <>
      <SidebarToggle
        sidebarOpen={sidebarOpen}
        showSidebar={showSidebar}
        onClick={toggleSidebar}
        size="small"
        aria-label={sidebarOpen ? "Hide sidebar" : "Show sidebar"}
      >
        {sidebarOpen ? (
          <ChevronLeftIcon fontSize="small" />
        ) : (
          <ChevronRightIcon fontSize="small" />
        )}
      </SidebarToggle>

      <SidebarContainer
        sidebarOpen={sidebarOpen}
        showSidebar={showSidebar}
        component="aside"
        role="navigation"
        aria-label="User navigation"
      >
        {/* Enhanced banner with avatar overlay */}
        <BannerContainer>
          <BannerImage image={userBanner} />
          <Tooltip
            title={`Visit ${userData.name}'s profile`}
            arrow
            placement="bottom"
          >
            <AvatarWrapper
              to={`/user/profile/${userData.name}`}
              onClick={handleProfileClick}
              aria-label={`Go to ${userData.name}'s profile`}
            >
              <ProfileAvatar src={userData.avatar?.large} alt={userData.name} />
            </AvatarWrapper>
          </Tooltip>
        </BannerContainer>

        {/* Main sidebar content */}
        {drawerContent}
      </SidebarContainer>
    </>
  );
};

export default React.memo(UserSidebar);