import React from "react";
import {
  Box,
  Card,
  CardContent,
  Typography,
  alpha,
  useTheme,
  Tooltip
} from "@mui/material";
import StyleIcon from "@mui/icons-material/Style";

/**
 * Tags Module component that shows a tag cloud visualization of the user's anime/manga tags
 */
const TagsModule = ({ stats, mediaType, paperStyles }) => {
  const theme = useTheme();
  
  if (!stats || !stats[mediaType]) {
    return (
      <Card sx={{ ...paperStyles, mb: 3 }}>
        <CardContent>
          <Typography variant="h6">Tag Cloud</Typography>
          <Typography variant="body2" color="text.secondary">
            No tags data available.
          </Typography>
        </CardContent>
      </Card>
    );
  }
  
  const currentStats = stats[mediaType];
  
  // Get tags data from user statistics
  const tagsData = currentStats.tags || [];
  
  // Sort tags by count and take top 30
  const sortedTags = [...tagsData]
    .sort((a, b) => b.count - a.count)
    .slice(0, 30);
  
  // If no tags data available
  if (sortedTags.length === 0) {
    return (
      <Card sx={{ ...paperStyles, mb: 3 }}>
        <CardContent>
          <Typography variant="h6">Tag Cloud</Typography>
          <Typography variant="body2" color="text.secondary">No tags data available.</Typography>
        </CardContent>
      </Card>
    );
  }
  
  // Find the max count to normalize sizes
  const maxCount = Math.max(...sortedTags.map(tag => tag.count));
  
  // Generate colors for the tags
  const generateTagColors = (count) => {
    const colors = [];
    
    // Primary color
    const primary = theme.palette.primary.main;
    
    // Secondary colors
    const secondary = [
      theme.palette.secondary.main,
      theme.palette.info.main,
      theme.palette.success.main,
      theme.palette.warning.main,
      theme.palette.error.main
    ];
    
    // Generate a gradient of colors
    for (let i = 0; i < count; i++) {
      const colorIndex = i % secondary.length;
      const color = secondary[colorIndex];
      colors.push(color);
    }
    
    return colors;
  };
  
  const tagColors = generateTagColors(sortedTags.length);
  
  return (
    <Card 
      sx={{ 
        ...paperStyles, 
        mb: 3,
        overflow: 'hidden',
        transition: 'all 0.3s ease',
        '&:hover': {
          boxShadow: 6
        }
      }}
    >
      <CardContent>
        <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
          <StyleIcon sx={{ color: theme.palette.secondary.main, mr: 1 }} />
          <Typography variant="h6" sx={{ fontWeight: 600 }}>
            Tag Cloud
          </Typography>
        </Box>
        
        <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
          Your most frequent {mediaType} tags
        </Typography>
        
        <Box 
          sx={{ 
            display: 'flex', 
            flexWrap: 'wrap', 
            justifyContent: 'center',
            alignItems: 'center',
            p: 1,
            minHeight: 160,
            maxHeight: 220,
            overflow: 'hidden'
          }}
        >
          {sortedTags.map((tag, index) => {
            // Calculate font size based on count (between 0.7rem and 2rem)
            const fontSize = 0.7 + ((tag.count / maxCount) * 1.3);
            
            // Calculate opacity based on count (between 0.7 and 1)
            const opacity = 0.7 + ((tag.count / maxCount) * 0.3);
            
            // Animation delay based on index
            const animDelay = index * 0.05;
            
            return (
              <Box
                key={tag.tag.id}
                sx={{
                  m: 0.5,
                  p: 0.75,
                  borderRadius: 1,
                  backgroundColor: alpha(tagColors[index % tagColors.length], 0.1),
                  border: `1px solid ${alpha(tagColors[index % tagColors.length], 0.2)}`,
                  transition: 'all 0.3s ease',
                  transform: 'scale(0.9)',
                  animation: `fadeIn 0.5s ease ${animDelay}s forwards`,
                  '@keyframes fadeIn': {
                    '0%': { opacity: 0, transform: 'scale(0.8)' },
                    '100%': { opacity: 1, transform: 'scale(1)' }
                  },
                  '&:hover': {
                    transform: 'scale(1.1) rotate(2deg)',
                    backgroundColor: alpha(tagColors[index % tagColors.length], 0.2),
                    zIndex: 1
                  }
                }}
              >
                <Tooltip 
                  title={
                    <Box>
                      <Typography variant="body2">{tag.tag.name}</Typography>
                      <Typography variant="caption">
                        Count: {tag.count} {mediaType}<br/>
                        Mean score: {tag.meanScore?.toFixed(1) || 'N/A'}
                      </Typography>
                    </Box>
                  }
                >
                  <Typography 
                    variant="body2" 
                    sx={{ 
                      fontSize: `${fontSize}rem`,
                      fontWeight: tag.count > (maxCount / 2) ? 600 : 400,
                      opacity,
                      color: tagColors[index % tagColors.length],
                      cursor: 'pointer',
                      whiteSpace: 'nowrap'
                    }}
                  >
                    {tag.tag.name}
                  </Typography>
                </Tooltip>
              </Box>
            );
          })}
        </Box>
        
        <Box sx={{ 
          display: 'flex', 
          justifyContent: 'center', 
          mt: 2,
          alignItems: 'center'
        }}>
          <Box sx={{ 
            width: 16, 
            height: 16, 
            borderRadius: '50%', 
            backgroundColor: alpha(tagColors[0], 0.8),
            mr: 1 
          }} />
          <Typography variant="caption" sx={{ mr: 2 }}>Popular</Typography>
          
          <Box sx={{ 
            width: 16, 
            height: 16, 
            borderRadius: '50%', 
            backgroundColor: alpha(tagColors[tagColors.length - 1], 0.8),
            mr: 1 
          }} />
          <Typography variant="caption">Less common</Typography>
        </Box>
      </CardContent>
    </Card>
  );
};

export default TagsModule;
