import React from "react";
import {
  Box,
  Card,
  CardContent,
  Typography,
  alpha,
  useTheme,
  Tooltip
} from "@mui/material";
import {
  PieChart,
  Pie,
  Cell,
  ResponsiveContainer,
  Tooltip as RechartsTooltip,
  Legend
} from "recharts";
import CheckCircleIcon from "@mui/icons-material/CheckCircle";

/**
 * Status Distribution component that shows the user's anime/manga by status
 */
const StatusDistribution = ({ stats, mediaType, paperStyles, generateColors }) => {
  const theme = useTheme();
  
  if (!stats || !stats[mediaType]) {
    return (
      <Card sx={{ ...paperStyles, mb: 3 }}>
        <CardContent>
          <Typography variant="h6">Status Distribution</Typography>
          <Typography variant="body2" color="text.secondary">
            No status data available.
          </Typography>
        </CardContent>
      </Card>
    );
  }
  
  const currentStats = stats[mediaType];
  
  // Prepare data for status distribution
  const statusData = currentStats.statuses.map(status => ({
    name: status.status.charAt(0) + status.status.slice(1).toLowerCase().replace('_', ' '),
    value: status.count,
    minutesWatched: status.minutesWatched
  }));
  
  // Generate status colors
  const statusColors = {
    Completed: theme.palette.success.main,
    Current: theme.palette.info.main,
    Planning: theme.palette.primary.main,
    Dropped: theme.palette.error.main,
    Paused: theme.palette.warning.main
  };
  
  return (
    <Card 
      sx={{ 
        ...paperStyles, 
        mb: 3,
        overflow: 'hidden',
        transition: 'transform 0.3s ease, box-shadow 0.3s ease',
        '&:hover': {
          boxShadow: 6
        } 
      }}
    >
      <CardContent>
        <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
          <CheckCircleIcon sx={{ color: theme.palette.success.main, mr: 1 }} />
          <Typography variant="h6" sx={{ fontWeight: 600 }}>
            Status Distribution
          </Typography>
        </Box>
        
        <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
          Breakdown of your {mediaType} by status
        </Typography>
        
        <Box sx={{ height: 300 }}>
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Pie
                data={statusData}
                cx="50%"
                cy="50%"
                labelLine={false}
                outerRadius={120}
                fill="#8884d8"
                dataKey="value"
                label={({ name, percent }) => `${name}: ${(percent * 100).toFixed(0)}%`}
                animationDuration={1500}
                animationBegin={300}
              >
                {statusData.map((entry, index) => (
                  <Cell 
                    key={`cell-${index}`} 
                    fill={statusColors[entry.name] || generateColors(statusData.length)[index % generateColors(statusData.length).length]} 
                  />
                ))}
              </Pie>
              <RechartsTooltip 
                formatter={(value, name, props) => [
                  `${value} ${mediaType} (${((value / currentStats.count) * 100).toFixed(1)}%)${
                    props.payload.minutesWatched ? ` • ${Math.round(props.payload.minutesWatched / 60)} hours` : ''
                  }`, 
                  name
                ]} 
              />
              <Legend 
                formatter={(value, entry, index) => (
                  <span style={{ color: entry.color }}>{value}</span>
                )}
                layout="horizontal"
                verticalAlign="bottom"
                align="center"
              />
            </PieChart>
          </ResponsiveContainer>
        </Box>
        
        {/* Quick stats under the chart */}
        <Box 
          sx={{ 
            display: 'flex', 
            flexWrap: 'wrap', 
            justifyContent: 'center',
            mt: 2,
            gap: 2
          }}
        >
          {statusData.map((status) => (
            <Tooltip 
              key={status.name} 
              title={`${status.value} ${mediaType} with status ${status.name}`}
            >
              <Box 
                sx={{ 
                  display: 'flex', 
                  flexDirection: 'column', 
                  alignItems: 'center'
                }}
              >
                <Typography 
                  variant="caption" 
                  color="text.secondary"
                  sx={{ mb: 0.5 }}
                >
                  {status.name}
                </Typography>
                <Typography 
                  variant="h6" 
                  sx={{ 
                    fontWeight: 'bold',
                    color: statusColors[status.name] || theme.palette.text.primary
                  }}
                >
                  {status.value}
                </Typography>
              </Box>
            </Tooltip>
          ))}
        </Box>
      </CardContent>
    </Card>
  );
};

export default StatusDistribution;
