import React from "react";
import PropTypes from "prop-types";
import { formatDistanceToNow } from "date-fns";
import {
  Box,
  Typography,
  Grid,
  Card,
  CardMedia,
  CardContent,
  Link,
  Tooltip,
  IconButton,
} from "@mui/material";
import FavoriteIcon from "@mui/icons-material/Favorite";
import ChatBubbleOutlineIcon from "@mui/icons-material/ChatBubbleOutline";

// Helper function to get the progress text
const getProgressText = ({ status, progress }) => {
  const upperStatus = (status || "").trim().toUpperCase();
  switch (upperStatus) {
    case "PLANS TO READ":
      return "Plans to read";
    case "COMPLETED":
      return "Finished reading";
    case "DROPPED":
      return "Dropped";
    case "PAUSED":
      return "Paused reading";
    case "REPEATING":
      return "Re-reading";
    default:
      if (progress) {
        const progressRange = progress.split("-");
        return progressRange.length === 2
          ? `Reads chapters ${progressRange[0]}-${progressRange[1]} of`
          : `Reads chapter ${progress} of`;
      }
      return "Reading";
  }
};

// Shortened timeAgo function
const formatTimeAgo = (timestamp) => {
  return formatDistanceToNow(new Date(timestamp * 1000), {
    addSuffix: true,
  })
    .replace("about ", "")
    .replace(/minute/g, "min")
    .replace(/hour/g, "hr")
    .replace(/second/g, "sec")
    .replace(/month/g, "mo")
    .replace(/year/g, "yr")
    .replace("less than a min", "<1 min");
};

const MemoizedActivityCard = React.memo(({ activity }) => {
  const { id, createdAt, media, status, progress } = activity;
  const timeAgo = formatTimeAgo(createdAt);
  const title = media?.title?.userPreferred || "Unknown Title";
  const coverImage = media?.coverImage?.large || "default-cover.jpg";
  const mediaId = media?.id || "";
  const mediaLink = `https://anilist.co/manga/${mediaId}`;
  const upperStatus = (status || "").toUpperCase();

  return (
    <Grid item xs={12} sm={6} key={id}>
      <Card
        variant="outlined"
        sx={{
          display: "flex",
          borderRadius: 2,
          height: 80,
          transition: "box-shadow 0.2s ease",
          "&:hover": {  },
        }}
      >
        {/* Cover Image - 10% */}
        <Tooltip title="View on AniList" arrow>
          <Link
            href={mediaLink}
            target="_blank"
            rel="noopener"
            sx={{ display: "block", cursor: "pointer", width: "10%" }}
          >
            <CardMedia
              component="img"
              image={coverImage}
              alt={title}
              sx={{
                height: "100%",
                objectFit: "cover",
                borderTopLeftRadius: 8,
                borderBottomLeftRadius: 8,
              }}
            />
          </Link>
        </Tooltip>

        {/* Content Area - 70% */}
        <Box
          sx={{
            display: "flex",
            flexDirection: "column",
            width: "70%",
            py: 1,
            pr: 0,
            pl: 2,
            justifyContent: "space-between",
            position: "relative",
            overflow: "hidden",
          }}
        >
          <CardContent sx={{ p: 0, "&:last-child": { pb: 0 } }}>
            <Typography
              variant="body2"
              sx={{
                display: "-webkit-box",
                WebkitBoxOrient: "vertical",
                WebkitLineClamp: 3,
                overflow: "hidden",
                textOverflow: "ellipsis",
                fontWeight: 400,
                color: "text.secondary",
              }}
            >
              {getProgressText({ status, progress })}
              {upperStatus !== "PLANNING" && (
                <Link
                  href={mediaLink}
                  target="_blank"
                  rel="noopener"
                  underline="hover"
                  sx={{
                    ml: 0.5,
                    fontWeight: 500,
                    color: "text.primary",
                    "&:hover": { color: "primary.main" },
                  }}
                >
                  {title}
                </Link>
              )}
            </Typography>
          </CardContent>
        </Box>

        {/* Time and Actions - 20% */}
        <Box
          aria-label="activity-right"
          sx={{
            width: "20%",
            display: "flex",
            flexDirection: "column",
            justifyContent: "space-between",
            alignItems: "flex-end",
            p: 1,
          }}
        >
          {/* Time at top right */}
          <Box
            aria-label="time ago"
            sx={{
              display: "flex",
              flexDirection: "column",
              alignItems: "flex-end",
              justifyContent: "flex-start",
              width: "100%",
              height: "100%",
            }}
          >
            <Typography
              variant="caption"
              color="text.secondary"
              sx={{
                fontSize: "0.7rem",
                whiteSpace: "nowrap",
              }}
            >
              {timeAgo}
            </Typography>
            <Box
              aria-label="additional-container"
              sx={{
                mt: "auto",
              }}
            >
            </Box>
          </Box>

          {/* Action icons at bottom right */}
          <Box
            aria-label="activity actions"
            
            sx={{
              display: "flex",
              flexDirection: "column",
              alignItems: "flex-end",
            }}
          >
            <Box sx={{ display: "flex", gap: 0.5 }}>
              <IconButton size="small" aria-label="like" sx={{ p: 0 }}>
                <FavoriteIcon sx={{ fontSize: 16 }} />
              </IconButton>
              <IconButton size="small" aria-label="comment" sx={{ p: 0  }}>
                <ChatBubbleOutlineIcon sx={{ fontSize: 16  }} />
              </IconButton>
            </Box>
          </Box>
        </Box>
      </Card>
    </Grid>
  );
});

MemoizedActivityCard.propTypes = {
  activity: PropTypes.shape({
    id: PropTypes.number.isRequired,
    status: PropTypes.string,
    progress: PropTypes.string,
    type: PropTypes.string.isRequired,
    createdAt: PropTypes.number.isRequired,
    media: PropTypes.shape({
      id: PropTypes.number,
      title: PropTypes.shape({
        userPreferred: PropTypes.string,
      }),
      coverImage: PropTypes.shape({
        large: PropTypes.string,
      }),
    }),
  }).isRequired,
};

const ActivityDisplay = React.memo(({ activities = [] }) => {
  return (
    <Box sx={{ px: 2, py: 1 }}>
     
      <Grid container spacing={1}>
        {activities.map((activity) => (
          <MemoizedActivityCard key={activity.id} activity={activity} />
        ))}
        {activities.length === 0 && (
          <Typography variant="body2" sx={{ p: 2, color: "text.secondary" }}>
            No recent activity to display.
          </Typography>
        )}
      </Grid>
    </Box>
  );
});

ActivityDisplay.propTypes = {
  activities: PropTypes.arrayOf(
    PropTypes.shape({
      id: PropTypes.number.isRequired,
      status: PropTypes.string,
      progress: PropTypes.string,
      type: PropTypes.string.isRequired,
      createdAt: PropTypes.number.isRequired,
      media: PropTypes.shape({
        id: PropTypes.number,
        title: PropTypes.shape({
          userPreferred: PropTypes.string,
        }),
        coverImage: PropTypes.shape({
          large: PropTypes.string,
        }),
      }),
    })
  ),
};

export default ActivityDisplay;
