// src/graphql/queries.js
const API_ENDPOINT = "https://graphql.anilist.co";
const CACHE_DURATION = 5 * 60 * 1000; // 5 minutes
/**
 * GraphQL query to fetch user profile data
 * @param {string} username - The username to query
 * @returns {string} GraphQL query string
 */
export const USER_QUERY = (username) => `
  query {
    User(name: "${username}") {
      id
      name
      about
      siteUrl
      avatar {
        medium
        large
      }
      bannerImage
      statistics {
        anime {
          count
          meanScore
          minutesWatched
          episodesWatched
        }
        manga {
          count
          meanScore
          chaptersRead
          volumesRead
        }
      }
      favourites {
        anime {
          nodes {
            id
            title {
              userPreferred
            }
            coverImage {
              medium
              large
            }
          }
        }
        manga {
          nodes {
            id
            title {
              userPreferred
            }
            coverImage {
              medium
              large
            }
          }
        }
        characters {
          nodes {
            id
            name {
              full
            }
            image {
              medium
              large
            }
          }
        }
        staff {
          nodes {
            id
            name {
              full
            }
            image {
              medium
              large
            }
          }
        }
      }
    }
  }
`;

