/**
 * Creates a GraphQL client for AniList
 * @param {object} options - Request options
 * @returns {Promise} - API response
 */
export const fetchFromAniList = async (query, variables = {}) => {
  const cacheKey = JSON.stringify({ query, variables });
  const cached = sessionStorage.getItem(cacheKey);
  
  if (cached) {
    try {
      const { timestamp, data } = JSON.parse(cached);
      if (Date.now() - timestamp < CACHE_DURATION) {
        console.log("Returning cached data for:", variables);
        return data;
      }
    } catch (error) {
      console.warn("Error parsing cached data:", error);
      // Continue to fetch fresh data
    }
  }

  let retries = 0;
  const MAX_RETRIES = 3;

  while (retries <= MAX_RETRIES) {
    try {
      console.log(`Making AniList API request with variables:`, variables);
      
      const response = await fetch(API_ENDPOINT, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Accept": "application/json",
        },
        body: JSON.stringify({ 
          query, 
          variables 
        }),
      });

      if (!response.ok) {
        const statusText = response.statusText;
        const status = response.status;
        
        // Enhanced error logging
        console.error(`API Error (${status}): ${statusText}`);
        
        // Handle rate limiting specifically
        if (status === 429) {
          retries++;
          const retryAfter = response.headers.get('Retry-After') || 60;
          console.warn(`Rate limited. Retrying after ${retryAfter}s (Attempt ${retries}/${MAX_RETRIES})`);
          
          if (retries <= MAX_RETRIES) {
            await new Promise(resolve => setTimeout(resolve, retryAfter * 1000));
            continue;
          }
        }
        
        throw new Error(`API request failed: ${status} ${statusText}`);
      }

      const data = await response.json();
      
      // Check for GraphQL errors in the response
      if (data.errors && data.errors.length > 0) {
        console.error("GraphQL errors:", data.errors);
        throw new Error(`GraphQL error: ${data.errors[0].message}`);
      }
      
      // Log successful response
      console.log("API response:", data);
      
      // Cache the successful response
      try {
        sessionStorage.setItem(cacheKey, JSON.stringify({
          timestamp: Date.now(),
          data: data.data
        }));
      } catch (error) {
        console.warn("Failed to cache response:", error);
      }
      
      return data.data;
    } catch (error) {
      retries++;
      
      // More detailed error logging
      console.error(`API request failed (attempt ${retries}/${MAX_RETRIES + 1}):`, error.message);
      
      if (retries <= MAX_RETRIES) {
        // Exponential backoff with jitter
        const delay = Math.min(1000 * Math.pow(2, retries) + Math.random() * 1000, 10000);
        console.warn(`Retrying in ${Math.round(delay / 1000)} seconds...`);
        await new Promise(resolve => setTimeout(resolve, delay));
      } else {
        console.error("Maximum retries exceeded. Giving up.");
        throw error;
      }
    }
  }
};