import React, { useEffect, useState, useCallback, useMemo } from "react";
import { Box, Container, CssBaseline, Typography, CircularProgress, Alert, ToggleButton, ToggleButtonGroup, Divider, alpha } from "@mui/material";
import { useThemeContext } from "../components/themeContext";
import AniListFilter from "./anilist/anilistFilter";
import Pagination from "./anilist/paginationWrapper";
import MediaEntry from "./anilist/mediaEntry";
import { useAniListData } from "../components/anilist/hooks/useAnilistData";
import { useMediaFilters } from "../components/anilist/hooks/useMediaFilters";
import { ErrorBoundary } from "react-error-boundary";
import { FixedSizeList } from 'react-window';

const ITEMS_PER_PAGE = 12;

const AniListComponent = ({
  defaultMediaType = "ANIME",
  compactView = false,
  fixedUsername = null,
  hideMediaToggle = false
}) => {
  const { currentTheme } = useThemeContext();
  const contrastColor = currentTheme.palette.text.primary;
  const isDark = currentTheme.palette.mode === "dark";
  
  const [mediaType, setMediaType] = useState(defaultMediaType);
  const [username, setUsername] = useState(fixedUsername || "ajisai");
  
  const { 
    mediaList, 
    loading, 
    error, 
    genresWithCount, 
    fetchData 
  } = useAniListData(username, mediaType);
  
  const {
    filteredList,
    paginatedItems,
    currentPage,
    searchTerm,
    selectedStatus,
    selectedGenre,
    sortBy,
    setCurrentPage,
    handleSearchChange,
    handleStatusChange,
    handleGenreChange,
    setSortBy,
    resetFilters
  } = useMediaFilters(mediaList, ITEMS_PER_PAGE);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const handleMediaTypeChange = useCallback((event, newMediaType) => {
    if (newMediaType) {
      setMediaType(newMediaType);
      setCurrentPage(1);
    }
  }, [setCurrentPage]);

  const handleUsernameChange = useCallback((newUsername) => {
    setUsername(newUsername);
    setCurrentPage(1);
  }, [setCurrentPage]);

  const formatDate = useCallback((date) => {
    if (!date?.year || !date?.month || !date?.day) return null;
    return `${date.year}-${date.month.toString().padStart(2, "0")}-${date.day.toString().padStart(2, "0")}`;
  }, []);

  const progressKey = useMemo(() => 
    mediaType === "ANIME" ? "episodes" : "chapters",
  [mediaType]);

  const titleStyle = compactView ? {
    variant: "h5",
    sx: {
      fontSize: "1.5rem",
      mb: 2,
      background: "linear-gradient(45deg, #ff3b6c 0%, #ff758c 100%)",
      WebkitBackgroundClip: "text",
      WebkitTextFillColor: "transparent",
    }
  } : {
    variant: "h3",
    sx: {
      mb: 4,
      fontSize: { xs: "2rem", sm: "3rem" },
      background: "linear-gradient(45deg, #ff3b6c 0%, #ff758c 100%)",
      WebkitBackgroundClip: "text",
      WebkitTextFillColor: "transparent",
    }
  };

  const containerStyle = compactView ? {
    py: 2,
    background: currentTheme.palette.background.default,
    minHeight: "auto",
  } : {
    py: 4,
    background: `linear-gradient(180deg, ${currentTheme.palette.background.default} 0%, ${alpha(currentTheme.palette.background.default, 0.8)} 100%)`,
    minHeight: "100vh",
  };

  return (
    <ErrorBoundary fallback={<Alert severity="error">Something went wrong. Please try again later.</Alert>}>
      <CssBaseline />
      <Box
        component="main"
        sx={{
          color: contrastColor,
          ...containerStyle
        }}
      >
        <Container maxWidth="xl" sx={{ my: compactView ? 2 : 6 }}>
          {!hideMediaToggle && (
            <>
              <Box sx={{ display: "flex", justifyContent: "center", mb: 2 }}>
                <ToggleButtonGroup
                  value={mediaType}
                  exclusive
                  onChange={handleMediaTypeChange}
                  aria-label="Media type switch"
                >
                  <ToggleButton
                    value="ANIME"
                    aria-label="Anime list"
                    sx={{
                      borderRadius: 50,
                      px: 4,
                      py: 1,
                      backgroundColor: isDark ? currentTheme.palette.background.paper : undefined,
                      "&.Mui-selected": {
                        background: "linear-gradient(45deg, #ff3b6c 0%, #ff758c 100%)",
                        color: "white",
                      },
                    }}
                  >
                    Anime
                  </ToggleButton>
                  <ToggleButton
                    value="MANGA"
                    aria-label="Manga list"
                    sx={{
                      borderRadius: 50,
                      px: 4,
                      py: 1,
                      backgroundColor: isDark ? currentTheme.palette.background.paper : undefined,
                      "&.Mui-selected": {
                        background: "linear-gradient(45deg, #ff3b6c 0%, #ff758c 100%)",
                        color: "white",
                      },
                    }}
                  >
                    Manga
                  </ToggleButton>
                </ToggleButtonGroup>
              </Box>
              <Divider sx={{ mb: 2 }} />
            </>
          )}

          <Typography
            variant={titleStyle.variant}
            component="h1"
            align="center"
            sx={titleStyle.sx}
          >
            {mediaType === "ANIME" ? "ANIME LIST" : "MANGA LIST"}
          </Typography>

          <Divider sx={{ mb: compactView ? 2 : 4 }} />

          <AniListFilter
            username={username}
            searchTerm={searchTerm}
            selectedStatus={selectedStatus}
            selectedGenre={selectedGenre}
            sortBy={sortBy}
            genresWithCount={genresWithCount}
            onUsernameChange={handleUsernameChange}
            onSearchChange={handleSearchChange}
            onStatusChange={handleStatusChange}
            onGenreChange={handleGenreChange}
            onSortChange={setSortBy}
            onResetFilters={resetFilters}
            compact={compactView}
            fixedUsername={!!fixedUsername}
          />

          <Divider sx={{ my: compactView ? 2 : 4 }} />

          {filteredList.length > 0 && (
            <Box sx={{ my: 2 }}>
              <Pagination
                totalItems={filteredList.length}
                itemsPerPage={ITEMS_PER_PAGE}
                currentPage={currentPage}
                onPageChange={setCurrentPage}
              />
            </Box>
          )}

          <Box sx={{ my: compactView ? 1 : 2 }} aria-live="polite">
            {loading ? (
              <Box sx={{ textAlign: "center", py: 4 }}>
                <CircularProgress />
                <Typography variant="h6" sx={{ mt: 2 }}>
                  Loading data...
                </Typography>
              </Box>
            ) : error ? (
              <Alert severity="error">{error}</Alert>
            ) : mediaList.length === 0 ? (
              <Alert severity="info">
                No {mediaType === "ANIME" ? "anime" : "manga"} list found for this user.
              </Alert>
            ) : paginatedItems.length === 0 ? (
              <Alert severity="info">No results found for current filters.</Alert>
            ) : compactView ? (
              <FixedSizeList
                height={400}
                itemCount={paginatedItems.length}
                itemSize={100}
                width="100%"
                overscanCount={5}
              >
                {({ index, style }) => (
                  <Box style={style}>
                    <MediaEntry 
                      entry={paginatedItems[index]} 
                      formatDate={formatDate}
                      progressKey={progressKey}
                      compact
                    />
                  </Box>
                )}
              </FixedSizeList>
            ) : (
              <Box 
                component="ul" 
                sx={{
                  display: "flex",
                  flexDirection: "column",
                  gap: 2,
                  p: 0,
                  m: 0,
                  listStyle: "none"
                }}
              >
                {paginatedItems.map((entry) => (
                  <MediaEntry
                    key={`${entry.media.id}-${entry.progress}-${entry.status}`}
                    entry={entry}
                    formatDate={formatDate}
                    progressKey={progressKey}
                  />
                ))}
              </Box>
            )}
          </Box>

          {filteredList.length > 0 && !loading && (
            <Box sx={{ my: 2 }}>
              <Pagination
                totalItems={filteredList.length}
                itemsPerPage={ITEMS_PER_PAGE}
                currentPage={currentPage}
                onPageChange={setCurrentPage}
              />
            </Box>
          )}
        </Container>
      </Box>
    </ErrorBoundary>
  );
};

export default React.memo(AniListComponent);