// hooks/useMediaFilters.js
import { useState, useMemo, useCallback, useEffect } from 'react';
import debounce from 'lodash.debounce';
import { useLocalStorage } from './useLocalStorage';

// Prevents unnecessary re-renders with stable filter state
export const useMediaFilters = (mediaList, itemsPerPage) => {
  const [selectedStatus, setSelectedStatus] = useLocalStorage("selectedStatus", "ALL");
  const [selectedGenre, setSelectedGenre] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [sortBy, setSortBy] = useState("title");
  const [searchTerm, setSearchTerm] = useState("");

  // Reset pagination on filter changes
  useEffect(() => setCurrentPage(1), [selectedStatus, selectedGenre, searchTerm, sortBy]);

  // Memoized search preprocessing with proper dependency tracking
  const preprocessedList = useMemo(() => 
    mediaList.map(entry => ({
      ...entry,
      searchString: [
        entry.media.title?.romaji?.toLowerCase(),
        entry.media.title?.english?.toLowerCase(),
        ...(entry.media.tags?.map(t => t.name?.toLowerCase()) || []),
        ...(entry.media.genres?.map(g => g.toLowerCase()) || [])
      ].join(' ')
    })), 
    [mediaList]
  );
  

  // Optimized filter functions
const filteredList = useMemo(() => {
  const normalizedSearch = searchTerm.trim().toLowerCase();
  const lowerSelectedGenre = selectedGenre.toLowerCase();

  return preprocessedList.filter(({ status, media, searchString }) => { // Fixed parameter
    const statusMatch = selectedStatus === "ALL" || status === selectedStatus;
    const genreMatch = !selectedGenre || 
      media.genres?.some(g => g.toLowerCase() === lowerSelectedGenre);
    const searchMatch = !normalizedSearch || 
      searchString.includes(normalizedSearch); // Fixed variable name

    return statusMatch && genreMatch && searchMatch;
  });
}, [preprocessedList, selectedStatus, selectedGenre, searchTerm]);
  // Memoized collator for sorting
  const collator = useMemo(() => new Intl.Collator(undefined, { 
    sensitivity: "base",
    numeric: true 
  }), []);

  // Optimized sorting with stable reference
  const sortedList = useMemo(() => {
    if (!filteredList.length) return [];
    
    return [...filteredList].sort((a, b) => {
      switch(sortBy) {
        case "title": 
          return collator.compare(
            a.media.title.romaji || '', 
            b.media.title.romaji || ''
          );
        case "score":
          return (b.score || 0) - (a.score || 0);
        case "progress":
          return (b.progress || 0) - (a.progress || 0);
        default: return 0;
      }
    });
  }, [filteredList, sortBy, collator]);

  // Pagination with bounds checking
  const paginatedItems = useMemo(() => {
    const start = (currentPage - 1) * itemsPerPage;
    return sortedList.slice(start, start + itemsPerPage);
  }, [sortedList, currentPage, itemsPerPage]);

  // Debounced search with cleanup
  const debouncedSearchChange = useCallback(
    debounce(query => setSearchTerm(query.trim()), 300),
    []
  );

  // Stable filter handlers
  const handleSearchChange = useCallback(
    query => debouncedSearchChange(query),
    [debouncedSearchChange]
  );

  const handleStatusChange = useCallback(value => {
    setSelectedStatus(value);
  }, [setSelectedStatus]);

  const handleGenreChange = useCallback(value => {
    setSelectedGenre(value);
  }, []);

  const resetFilters = useCallback(() => {
    setSelectedStatus("ALL");
    setSelectedGenre("");
    setSortBy("title");
    setSearchTerm("");
    setCurrentPage(1);
  }, [setSelectedStatus]);

  return {
    filteredList,
    sortedList,
    paginatedItems,
    currentPage,
    searchTerm,
    selectedStatus,
    selectedGenre,
    sortBy,
    setCurrentPage,
    handleSearchChange,
    handleStatusChange,
    handleGenreChange,
    setSortBy,
    resetFilters
  };
};